// Python版と同様、モーダル選択をまたいで表示したメンバーそのも
// のを保持する。 ゲーム側の所有スレッドで名前・識別情報を一緒に取得
// し、 UIの結果と予約した変更まで保持する。後の行順は使わない。
struct DebuggerMemberSnapshot : ::cw::lib::Object {
    std::vector<std::shared_ptr<::cw::character::Character>> members;
    std::vector<::cw::lib::String> labels;
};
struct DebuggerMemberSelectionEvent : ::cw::lib::Window {
    std::shared_ptr<::cw::character::Character> member;
};
std::shared_ptr<DebuggerMemberSnapshot> debugger_member_snapshot()
{
    const auto engine = ::cw::g_cwpy;
    if (!engine) return {};
    const auto value = engine->sync_exec([engine](const auto&, const auto&) {
        auto result = std::make_shared<DebuggerMemberSnapshot>();
        auto append = [&](const auto& cards, const char* prefix) {
            for (const auto& card : cards) if (card) {
                result->members.push_back(card);
                result->labels.push_back(::cw::lib::String(prefix) + card->m_name);
            }
        };
        append(engine->get_pcards({}), "Player: ");
        append(engine->get_ecards({}), "Enemy: ");
        append(engine->get_fcards({}), "Friend: ");
        return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(result));
    });
    const auto object = std::get_if<::cw::lib::ObjectPtr>(&value.storage());
    return object ? std::dynamic_pointer_cast<DebuggerMemberSnapshot>(*object) : nullptr;
}


#ifdef _WIN32
std::wstring native_wide(const ::cw::lib::String& text)
{
    if (text.empty()) return {};
    const int size = MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS,
        text.data(), static_cast<int>(text.size()), nullptr, 0);
    if (size <= 0) return std::wstring(text.begin(), text.end());
    std::wstring result(static_cast<std::size_t>(size), L'\0');
    MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, text.data(),
        static_cast<int>(text.size()), result.data(), size);
    return result;
}


#endif
