using Integer = ::cw::lib::Integer;

// Python版と同様、捕捉したBattleErrorを送るのは戦闘状態の間だけ。 C++
// のBattleEngineは共有所有のオブジェクトを受け取るため、 スタック上の例
// 外へのポインターではなく、定義された四つの制御型を複製する。 未知のBattleError
// は引き続きprocess_exceptionのassert経路を通る。
void forward_debugger_battle_error(const ::cw::battle::BattleError& error)
{
    const auto app = ::cw::g_cwpy;
    if (!app || !app->is_battlestatus()) return;
    if (!app->m_battle || !*app->m_battle)
        throw std::logic_error("debugger battle exception requires an active battle");
    std::shared_ptr<::cw::battle::BattleError> owned;
    if (const auto* typed = dynamic_cast<const ::cw::battle::BattleStartBattleError*>(&error))
        owned = std::make_shared<::cw::battle::BattleStartBattleError>(*typed);
    else if (const auto* typed = dynamic_cast<const ::cw::battle::BattleAreaChangeError*>(&error))
        owned = std::make_shared<::cw::battle::BattleAreaChangeError>(*typed);
    else if (const auto* typed = dynamic_cast<const ::cw::battle::BattleWinError*>(&error))
        owned = std::make_shared<::cw::battle::BattleWinError>(*typed);
    else if (const auto* typed = dynamic_cast<const ::cw::battle::BattleDefeatError*>(&error))
        owned = std::make_shared<::cw::battle::BattleDefeatError>(*typed);
    else
        owned = std::make_shared<::cw::battle::BattleError>(error);
    (*app->m_battle)->process_exception(std::move(owned));
}

// デバッガーの画面はPython互換の論理ppis()座標
// で定義し、表示境界でDebuggerDpiにより一度描画
// する。 SystemDialogMetricsはすでに
// デスクトップ画素なので、論理画面内で使って、 最終処理
// 後に一覧・ツリーの文字へ二度目のDPI拡大を掛けない。
::cw::lib::ui::SystemDialogMetrics debugger_logical_metrics()
{
    auto result = ::cw::lib::ui::system_dialog_metrics();
    const auto scale = (std::max<::cw::lib::Real>)(result.scale, 1.0);
    result.font.pixels = (std::max<Integer>)(1, static_cast<Integer>(
        std::lround(static_cast<::cw::lib::Real>(result.font.pixels) / scale)));
    result.line_height = (std::max<Integer>)(1, static_cast<Integer>(
        std::lround(static_cast<::cw::lib::Real>(result.line_height) / scale)));
    result.scale = 1.0;
    return result;
}

// ネイティブのデバッガー部品は文字列を返すが、対応するPython
// のダイアログは検証済み整数しか渡さない。 from_chars
// でこの境界を明示し、空白を飛ばさず、コンマ・全角
// 数字・末尾文字などを含む部分的な解析を拒否する。
std::optional<Integer> parse_integer(const ::cw::lib::String& text)
{
    if (text.empty())
        return std::nullopt;
    Integer value{};
    const auto result = std::from_chars(text.data(), text.data() + text.size(), value, 10);
    if (result.ec != std::errc{} || result.ptr != text.data() + text.size())
        return std::nullopt;
    return value;
}

std::optional<std::vector<Integer>> parse_integer_list(const ::cw::lib::String& text)
{
    // ネイティブの複数選択アダプターは、明示的な空選択にコン
    // マを使い、Pythonダイアログの空結果に対応させる。
    if (text == ",")
        return std::vector<Integer>{};
    if (text.empty())
        return std::nullopt;
    std::vector<Integer> result;
    std::size_t begin = 0;
    while (begin <= text.size()) {
        const auto end = text.find(',', begin);
        const auto token = text.substr(begin, end == ::cw::lib::String::npos
                                                ? end : end - begin);
        const auto value = parse_integer(token);
        if (!value)
            return std::nullopt;
        result.push_back(*value);
        if (end == ::cw::lib::String::npos)
            break;
        begin = end + 1;
    }
    return result;
}

Integer value_integer(const ::cw::lib::Value& value, Integer fallback = 0)
{
    if (const auto* integer = std::get_if<Integer>(&value.storage()))
        return *integer;
    if (const auto* real = std::get_if<::cw::lib::Real>(&value.storage()))
        return static_cast<Integer>(*real);
    if (const auto* boolean = std::get_if<bool>(&value.storage()))
        return *boolean ? 1 : 0;
    if (const auto* text = std::get_if<::cw::lib::String>(&value.storage())) {
        if (const auto result = parse_integer(*text))
            return *result;
    }
    return fallback;
}

::cw::lib::String value_string(const ::cw::lib::Value& value)
{
    if (const auto* text = std::get_if<::cw::lib::String>(&value.storage()))
        return *text;
    if (const auto* integer = std::get_if<Integer>(&value.storage()))
        return std::to_string(*integer);
    if (const auto* real = std::get_if<::cw::lib::Real>(&value.storage()))
        return std::to_string(*real);
    if (const auto* boolean = std::get_if<bool>(&value.storage()))
        return *boolean ? "true" : "false";
    return {};
}

void reload_debugger_current_skin()
{
    // Python版と同様、basename(cwpy.skindir)を渡し、changearea=true
    // を保ち、 開始アニメーションの再開だけを無効にする。
    const auto skin_name = ::cw::lib::encoding::path_to_utf8(
        std::filesystem::u8path(value_string(::cw::g_cwpy->m_skindir)).filename());
    ::cw::g_cwpy->update_skin(skin_name, true, false, std::nullopt, true, false);
}

bool value_bool(const ::cw::lib::Value& value, bool fallback = false)
{
    if (const auto* boolean = std::get_if<bool>(&value.storage()))
        return *boolean;
    if (const auto* integer = std::get_if<Integer>(&value.storage()))
        return *integer != 0;
    if (const auto* real = std::get_if<::cw::lib::Real>(&value.storage()))
        return *real != 0.0;
    if (const auto* text = std::get_if<::cw::lib::String>(&value.storage()))
        return *text == "1" || *text == "true" || *text == "True" || *text == "TRUE";
    return fallback;
}

