// ネイティブのデバッガー終了後に、ゲームのコールバックが完了する場
// 合がある。 Debuggerの非所有の互換別名を保持せず、Frame
// 経由でUI変更を予約し、その所有デバッガーを再確認する。
void post_debugger_ui(std::weak_ptr<::cw::frame::Frame> parent,
                      std::function<void(Debugger&)> operation)
{
    if (const auto frame = parent.lock()) {
        frame->exec_func([parent, operation = std::move(operation)](const auto&, const auto&) mutable {
            if (const auto current = parent.lock(); current && current->m_debugger &&
                *current->m_debugger && operation)
                operation(*(*current->m_debugger));
            return ::cw::lib::Value{};
        });
    }
}

void redraw_debugger_presentation(Debugger& debugger);

enum class DebuggerControl { StepReturn, StepOver, StepIn, TogglePause, Pause, Resume, Stop };

void post_debugger_control(std::weak_ptr<::cw::frame::Frame> parent,
                           DebuggerControl control)
{
    ::cw::lib::RuntimeAccess runtime_access;
    const auto game = ::cw::g_cwpy;
    if (!game || !game->m_event) return;
    const auto expected_event = game->m_event;
    // Pythonのインタープリターロックは、C++の状態反映の同期にはならな
    // い。 強制コマンドは停止・メッセージ・待機ループ内でもゲームの所有スレ
    // ッドで処理し、 先入れ先出しで連続するユーザーの制御要求の順序を保つ。
    game->force_exec_func([weak = std::weak_ptr<::cw::thread::CWPy>(game),
                          expected_event, parent, control](const auto&, const auto&) {
        const auto owner = weak.lock();
        if (!owner || owner->m_event != expected_event) return ::cw::lib::Value{};
        auto& event = *expected_event;
        if (control == DebuggerControl::Stop) {
            event.m__step = false;
            if (owner->is_runningevent()) {
                if (const auto message = owner->get_messagewindow(); message && *message) {
                    auto error = std::make_shared<::cw::event::EffectBreakError>();
                    error->initialize(true);
                    (*message)->m_result = std::static_pointer_cast<::cw::lib::Object>(error);
                    (*message)->m_result_typed.reset();
                } else event.set_stoped(true);
            }
            // イベントの巻き戻しが最終のデバッガー更新を管理する。 同期UI
            // コールバックから、巻き戻し途中のコンテントツリーを調べない。
            return ::cw::lib::Value{};
        }
        const bool step = control == DebuggerControl::StepReturn ||
                          control == DebuggerControl::StepOver ||
                          control == DebuggerControl::StepIn;
        event.m_breakwait = true;
        event.m__targetstack = control == DebuggerControl::StepReturn
            ? event.get_currentstack() - 1 : control == DebuggerControl::StepOver
            ? event.get_currentstack() : Integer{-2};
        event.m__step = step;
        event.m_paused = control == DebuggerControl::TogglePause ? !event.m_paused
            : control == DebuggerControl::Pause;
        if (step) {
            if (const auto message = owner->get_messagewindow(); message && *message) {
                owner->play_sound("click", true, 100, 1, 0, 0, false);
                (*message)->m_result = ::cw::lib::Value{Integer{0}};
                (*message)->m_result_typed = 0;
            }
        }
        const bool paused = event.m_paused;
        post_debugger_ui(parent, [paused](Debugger& debugger) {
            debugger.m_pause_checked = paused;
            debugger.refresh_tools();
            redraw_debugger_presentation(debugger);
        });
        return ::cw::lib::Value{};
    });
}

// 閉じて開き直したペインや置換後のデバッガーへ、古いワーカー結果を
// 送らない。 スレッド間で確認するのは、この原子的な購読状態だけ。
void post_stack_ui(std::weak_ptr<::cw::frame::Frame> parent,
    std::shared_ptr<std::atomic<std::uint64_t>> generation,std::uint64_t epoch,
    std::function<void(StackTraceView&)> update)
{
    if (!(epoch&1)) return;
    post_debugger_ui(parent,[generation,epoch,update=std::move(update)](Debugger& debugger) {
        if (debugger.m_stack_epoch!=generation || generation->load()!=epoch ||
            !debugger.m_visible || !debugger.m_view_stacktrace || !*debugger.m_view_stacktrace) return;
        update(**debugger.m_view_stacktrace);
        debugger.m_presentation_dirty.store(true,std::memory_order_release);
    });
}

void invalidate_debugger_host(Debugger& debugger)
{
    debugger.m_presentation_dirty.store(true, std::memory_order_release);
}

// 変数変更はエンジンスレッドから発生する。m_refresh_pending
// はモデル状態にすぎず、 wxのRefreshItem/Refresh
// と異なり、ネイティブ・組み込みデバッガーの描画を直接無効化しない。
// デバッガーのUIスレッドへ戻ってから、必ず変更後の現在値を反映する。
void redraw_variable_presentation(Debugger& debugger)
{
    if (debugger.m_view_var)
        debugger.m_view_var->m_refresh_pending = true;
    invalidate_debugger_host(debugger);
}

void redraw_debugger_presentation(Debugger& debugger)
{
    invalidate_debugger_host(debugger);
}

