void Debugger::initialize(std::shared_ptr<::cw::frame::Frame> arg_parent)
{
    cancel_document_request();
    initialize_ids();
    if (!g_mutex)
        g_mutex = std::make_shared<::cw::lib::Mutex>();
    // Objectは enable_shared_from_this を継承しない。 このフレー
    // ムの寿命の間は別名のshared_ptrを保持し、 EventView・VariableListCtrl
    // ・StackTraceViewが親の弱参照を安全に取得できるようにする。
    m_self = std::shared_ptr<Debugger>(this, [](Debugger*) {});
    m_parent_alias = arg_parent;
    m_parent = arg_parent;
    m_cwpy_debug = true;
    m_initialized = true;
    m_visible = true;
    m_bound = false;
    m_area_battletool = false;
    m_show_stacktrace = false;
    m_pause_checked = false;
    m_waittime = 0;
    retire_wait_input();
    m_areaid = ::cw::g_cwpy ? ::cw::g_cwpy->m_areaid : -1;
    m_area_label.clear();
    m_selectedmember_label.clear();
    m_selectedcard_label.clear();
    m_selectedcard_type.clear();
    m_bgm_path.clear();
    m_last_error.clear();
    m_forwarded_keys.clear();
    m_stack_epoch = std::make_shared<std::atomic<std::uint64_t>>(0);
    m_tool_enabled.clear();
    m_operation_log.clear();
    m_view_tree = std::make_shared<EventView>();
    m_view_var = std::make_shared<VariableListCtrl>();
    m_view_tree->initialize(m_self);
    m_view_var->initialize(m_self);
    m_view_stacktrace.reset();
    _bind();
    refresh_all();
}

void Debugger::refresh_all()
{
    if (!m_initialized)
        return;
    if (m_view_tree) {
        m_view_tree->refresh_tree();
        m_view_tree->refresh_activeitem();
    }
    if (m_view_var)
        m_view_var->refresh_variablelist_impl(std::nullopt);
    _refresh_tools();
    _refresh_areaname(true);
    _refresh_pausetool();
    // Python版と同様、二つのラベルはEventInterface
    // の現在値から作る。 イベント途中で開いても
    // 、次の選択通知まで「未定」のままにしない。
    if (::cw::g_cwpy && ::cw::g_cwpy->m_event) {
        m_selectedmember_label = ::cw::g_cwpy->m_event->get_selectedmembername();
        m_selectedcard_label = ::cw::g_cwpy->m_event->get_selectedcardname();
        const auto type = ::cw::g_cwpy->m_event->get_selectedcardtype();
        m_selectedcard_type = type ? *type : "";
    } else {
        m_selectedmember_label.clear();
        m_selectedcard_label.clear();
        m_selectedcard_type.clear();
    }
    redraw_debugger_presentation(*this);
}

void Debugger::_bind()
{
    initialize_ids();
    m_f1keyid = 1001;
    m_f2keyid = 1002;
    m_f3keyid = 1003;
    m_f4keyid = 1004;
    m_f5keyid = 1005;
    m_f6keyid = 1006;
    m_f7keyid = 1007;
    m_f8keyid = 1008;
    m_f9keyid = 1009;
    m_ctrl_d_keyid = 1010;
    m_bound = true;
    // UI実装は一つに統一する。外部表示・ALLとも
    // 、FrameのPresentationホストが
    // 唯一のウィンドウを管理する。 デバッガーモデ
    // ルは、追加のネイティブウィンドウを作らない。
    record(this, "bind");
}

void Debugger::OnF1KeyDown(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    m_forwarded_keys.push_back(1);
    if (::cw::g_cwpy) ::cw::g_cwpy->exec_func([](const auto&,const auto&){if(::cw::g_cwpy&&::cw::g_cwpy->m_keyevent){::cw::g_cwpy->m_keyevent->keydown(::cw::eventhandler::KEY_F1);::cw::g_cwpy->m_keyevent->keyup(::cw::eventhandler::KEY_F1);}return ::cw::lib::Value{};});
}

