void Debugger::OnUpdateTool(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if (!::cw::g_cwpy || ::cw::g_cwpy->is_runningevent())
        return;
    // Python版と同様、再読み込みを予約する前にガードを立て、全
    // デバッガー操作を直ちに無効にする。 予約コールバック内で設定す
    // ると、連続クリックで重複した再読み込みが積まれる時間が生じる。
    ::cw::g_cwpy->m_is_debuggerprocessing = true;
    refresh_tools();
    const auto parent = m_parent;
    ::cw::g_cwpy->exec_func([parent](const auto&, const auto&) {
        if (!::cw::g_cwpy || ::cw::g_cwpy->is_runningevent())
            return ::cw::lib::Value{};
        try {
            ::cw::g_cwpy->play_sound("click", false, 100, 1, 0, 0, false);
            if (const auto data = scenario_data()) {
                data->reload();
                if (::cw::g_cwpy->m_areaid >= 0 && !::cw::g_cwpy->m_selectedheader) {
                    ::cw::g_cwpy->change_area(
                        ::cw::g_cwpy->m_areaid, false, true,
                        {"Default", ::cw::lib::Value("Default")}, false, false,
                        false, true, std::nullopt, false, false, false, false, false);
                }
                if (::cw::g_cwpy->m_battle && *::cw::g_cwpy->m_battle) {
                    (*::cw::g_cwpy->m_battle)->ready();
                    --(*::cw::g_cwpy->m_battle)->m_round;
                }
            } else {
                reload_debugger_current_skin();
            }
            ::cw::g_cwpy->play_sound("signal", false, 100, 1, 0, 0, false);
        } catch (const ::cw::event::EffectBreakError&) {
        } catch (...) {
            post_debugger_ui(parent, [](Debugger& debugger) {
                debugger.m_last_error = "デバッグ情報の更新に失敗しました";
            });
        }
        ::cw::g_cwpy->m_is_debuggerprocessing = false;
        post_debugger_ui(parent, [](Debugger& debugger) {
            // ScenarioData::reload()は変数オブジェクト
            // を置き換える場合がある。 Python版のエンジンスレッドか
            // らwxスレッドへの更新と同様、完了後にだけ一覧を再構築する。
            debugger.refresh_all();
        });
        return ::cw::lib::Value{};
    });
}

void Debugger::OnRedisplayTool(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if (!::cw::g_cwpy)
        return;
    ::cw::g_cwpy->exec_func([](const auto&, const auto&) {
        if (!::cw::g_cwpy)
            return ::cw::lib::Value{};
        ::cw::g_cwpy->play_sound("harvest", false, 100, 1, 0, 0, false);
        if (::cw::g_cwpy->m_background) {
            ::cw::g_cwpy->m_background->reload(
                true, {"Default", ::cw::lib::Value("Default")}, true,
                {}, {}, {}, false, false);
        }
        ::cw::g_cwpy->add_lazydraw({});
        return ::cw::lib::Value{};
    });
    record(this, "redisplay_background");
}

