void Debugger::OnSavedJPDCImageTool(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (!::cw::g_cwpy) return;
    const auto frame_parent=m_parent;
    const auto generation=m_stack_epoch;
    const auto epoch=generation->load();
    const auto native_handle=arg_event?arg_event->native_handle:0;
    // Python版と同様、ゲーム側の所有スレッドでコンテナーを複製してからUI
    // を予約する。 保持したヘッダー・XMLは、元の浅い複製の同一性を維持する。
    ::cw::g_cwpy->exec_func([frame_parent,native_handle,generation,epoch,expected=this](const auto&,const auto&) {
        if (!::cw::g_cwpy || !::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata) return ::cw::lib::Value{};
        auto values=(*::cw::g_cwpy->m_ydata)->m_savedjpdcimage;
        post_debugger_ui(frame_parent,[values=std::move(values),native_handle,generation,epoch,expected](Debugger& owner) mutable {
            // C++の予約済み完了処理も、所有者の終了・再表示を確認する。
            if (&owner!=expected || !owner.m_visible || owner.m_stack_epoch!=generation || generation->load()!=epoch) return;
    auto parent = std::make_shared<::cw::lib::Window>();
    parent->title = "保存済みJPDCイメージ";
    if (native_handle)
        parent->native_handle = native_handle;
    else if (const auto frame = owner.m_parent.lock())
        parent->native_handle = frame->m_native_window_handle;
    auto dialog = std::make_shared<::cw::debug::edit::SavedJPDCImageEditDialog>();
    dialog->initialize(parent, values);
    (void)::cw::debug::edit::show_modal(*dialog);
        });
        return ::cw::lib::Value{};
    });
    record(this, "open_saved_jpdc_image_editor");
}

