void Debugger::OnAreaTool(std::shared_ptr<::cw::lib::Window> arg_event)
{
    // Python版と同様、メニューの有効化だけでなく、この入口自体を保護す
    // る。 数値タイトルによる自動操作も、同じシナリオ・イベント条件に従う。
    if (!::cw::g_cwpy || !::cw::g_cwpy->is_playingscenario() ||
        ::cw::g_cwpy->is_runningevent()) return;
    if (m_area_battletool && ::cw::g_cwpy) {
        ::cw::g_cwpy->exec_func([](const auto&, const auto&) {
            if (::cw::g_cwpy && ::cw::g_cwpy->m_battle && *::cw::g_cwpy->m_battle) {
                // Python版と同様、Battle.end()より前
                // にキャンプ・戦闘の特殊状態を消す。 デバッガーで戦闘
                // を離れたときに、一時的なカード・選択状態を残さない。
                ::cw::g_cwpy->clean_specials(false, false);
                (*::cw::g_cwpy->m_battle)->end();
            }
            return ::cw::lib::Value{};
        });
        record(this, "end_battle");
        return;
    }
    if (arg_event && !arg_event->title.empty()) {
        const auto resid = parse_integer(arg_event->title);
        if (!resid) {
            m_last_error = "エリアIDが正しくありません";
            return;
        }
        if (::cw::g_cwpy) {
            ::cw::g_cwpy->exec_func([](const auto&, const auto&) {
                if (::cw::g_cwpy) ::cw::g_cwpy->clean_specials(false, false);
                return ::cw::lib::Value{};
            });
            ::cw::g_cwpy->exec_func([resid = *resid](const auto&, const auto&) {
                Debugger_OnAreaTool_func2(resid);
                return ::cw::lib::Value{};
            });
        }
        record(this, "change_area");
        return;
    }
    if (::cw::g_cwpy && ::cw::g_cwpy->m_battle)
        record(this, "end_battle_for_area_selection");
    record(this, "open_area_selector");
}

void Debugger::OnSelectionTool(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (!m_view_tree || !m_view_tree->enable_eventview() ||
        !::cw::g_cwpy || !::cw::g_cwpy->is_runningevent()) return;
    if (::cw::g_cwpy && arg_event && !arg_event->title.empty()) {
        const auto index = parse_integer(arg_event->title);
        if (!index) {
            m_last_error = "メンバ選択値が正しくありません";
            return;
        }
        std::shared_ptr<::cw::character::Character> member;
        if (const auto selected = std::dynamic_pointer_cast<DebuggerMemberSelectionEvent>(arg_event)) {
            member = selected->member;
        } else {
            // ネイティブ独自のタイトル・位置入力は、呼び出し時の行を
            // 所有側で一度解決する。 通常のモーダルは開く前の対象識
            // 別情報を保持しているため、ここで位置を引き直さない。
            const auto snapshot = debugger_member_snapshot();
            if (snapshot && *index >= 0 && static_cast<std::size_t>(*index) < snapshot->members.size())
                member = snapshot->members[static_cast<std::size_t>(*index)];
        }
        if (!member) return;
        const auto engine = ::cw::g_cwpy;
        engine->exec_func([engine, member](const auto&, const auto&) {
            if (engine->m_event) engine->m_event->set_selectedmember(member);
            return ::cw::lib::Value{};
        });
        record(this, "set_selectedmember");
        return;
    }
    record(this, "open_member_selector");
    // デバッガーのツールクリックと同じ、有効な共通選択経路を使う。
    // 閉じた所有者は、モーダルを開く前にその振り分け処理が拒否する。
    if (::cw::g_cwpy) dispatch_command_id(id_value(g_ID_SELECTION));
}

void Debugger::OnSelectedCardTool(std::shared_ptr<::cw::lib::Window> arg_event)
{
    const bool nonactive_audit =
        ::cardwirth::debug::nonactive_automation_enabled();
    if (!::cw::g_cwpy || (!m_view_tree && !nonactive_audit)) return;
    if (arg_event && !arg_event->title.empty()) {
        if (!m_view_tree || !m_view_tree->enable_eventview() ||
            !::cw::g_cwpy->is_runningevent()) return;
        // ネイティブ独自の数値タイトル入力は荷物袋の行だけを対象とし、負値は解
        // 除を意味する。 通常のPython形式のモーダルは、荷物袋・保持中の
        // 手札・対応する全ポケットを集めるため、それを置き換えるものではない。
        const auto index = parse_integer(arg_event->title);
        if (!index) {
            m_last_error = "選択カードのインデックスが正しくありません";
            return;
        }
        const auto selected = *index;
        const auto engine = ::cw::g_cwpy;
        // Pythonのモーダル結果と同様、後の荷物袋編集で別カ
        // ードを指し得る行番号ではなく、選択ヘッダーを保持する
        // 。 荷物袋専用なのは、追加のタイトル・位置入力だけ。
        std::shared_ptr<::cw::header::CardHeader> header;
        if (selected >= 0) {
            const auto snapshot = engine->sync_exec([engine, selected](const auto&, const auto&) {
                if (!engine->m_ydata || !*engine->m_ydata ||
                    !(**engine->m_ydata).m_party || !*(**engine->m_ydata).m_party)
                    return ::cw::lib::Value{};
                const auto party = *(**engine->m_ydata).m_party;
                if (static_cast<std::size_t>(selected) >= party->m_backpack.size())
                    return ::cw::lib::Value{};
                return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(
                    party->m_backpack[static_cast<std::size_t>(selected)]));
            });
            const auto object = std::get_if<::cw::lib::ObjectPtr>(&snapshot.storage());
            header = object ? std::dynamic_pointer_cast<::cw::header::CardHeader>(*object) : nullptr;
            if (!header) return;
        }
        const auto view = m_view_tree;
        const auto generation = m_stack_epoch;
        const auto epoch = generation->load();
        engine->exec_func([engine, header, view, generation, epoch](const auto&, const auto&) {
            // Python版と同様、予約した結果の実行時にイベント表示・実行状態を再確認
            // する。 ネイティブの世代確認では、破棄されたモーダルの所有者も拒否する。
            if (generation->load() != epoch || ::cw::g_cwpy != engine ||
                !view || !view->enable_eventview() || !engine->is_runningevent() ||
                !engine->m_event) return ::cw::lib::Value{};
            if (header) engine->m_event->set_selectedcard(header);
            else engine->m_event->set_selectedcard(std::nullopt);
            return ::cw::lib::Value{};
        });
        record(this, "set_selectedcard");
        return;
    }
    const auto frame_parent=m_parent;
    const auto generation=m_stack_epoch;
    const auto epoch=generation->load();
    const auto native_handle=arg_event?arg_event->native_handle:0;
    ::cw::g_cwpy->exec_func([frame_parent,native_handle,nonactive_audit,generation,epoch,expected=this](const auto&,const auto&) {
        if (!::cw::g_cwpy || (!nonactive_audit && !(::cw::g_cwpy->is_playingscenario() || debug_skin_enabled())) || !::cw::g_cwpy->m_event || !::cw::g_cwpy->is_runningevent() ||
            !::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata || !(*::cw::g_cwpy->m_ydata)->m_party || !*(*::cw::g_cwpy->m_ydata)->m_party) return ::cw::lib::Value{};
    std::vector<std::tuple<::cw::lib::String,
                           std::vector<std::shared_ptr<::cw::header::CardHeader>>>> ccards;
    const auto party = *(*::cw::g_cwpy->m_ydata)->m_party;
    ccards.emplace_back("荷物袋", party->m_backpack);
    auto append_character = [&](const auto& character, const char* prefix) {
        if (!character)
            return;
        std::vector<std::shared_ptr<::cw::header::CardHeader>> cards;
        if (::cw::g_cwpy->is_battlestatus() && character->m_deck)
            // デバッガーは、破棄予定・非アクティブでも保持中の手
            // 札の複製を調べる。 ゲーム用の取得関数はそれを絞
            // り込み、使用済みカードも追加し得るため使わない。
            cards = character->m_deck->m_hand;
        else {
            const auto& pockets = character->m_cardpocket_typed;
            cards = std::get<0>(pockets);
            cards.insert(cards.end(), std::get<1>(pockets).begin(), std::get<1>(pockets).end());
        }
        cards.insert(cards.end(), std::get<2>(character->m_cardpocket_typed).begin(),
                     std::get<2>(character->m_cardpocket_typed).end());
        ccards.emplace_back(::cw::lib::String(prefix) + ": " + character->m_name,
                            std::move(cards));
    };
    for (const auto& character : ::cw::g_cwpy->get_pcards({}))
        append_character(character, "Player");
    for (const auto& character : ::cw::g_cwpy->get_ecards({}))
        append_character(character, "Enemy");
    for (const auto& character : ::cw::g_cwpy->get_fcards({}))
        append_character(character, "Friend");
    const auto selectedcard=::cw::g_cwpy->m_event->get_selectedcard();
    post_debugger_ui(frame_parent,[ccards=std::move(ccards),selectedcard,native_handle,generation,epoch,expected](Debugger& owner) mutable {
        // C++の予約済み完了処理も、所有者の終了・再表示を確認する。
            if (&owner!=expected || !owner.m_visible || owner.m_stack_epoch!=generation || generation->load()!=epoch) return;
    auto parent = std::make_shared<::cw::lib::Window>();
    parent->title = "選択カードの変更";
    if (native_handle)
        parent->native_handle = native_handle;
    else if (const auto frame = owner.m_parent.lock())
        parent->native_handle = frame->m_native_window_handle;
    auto dialog = std::make_shared<::cw::debug::selectedcard::SelectedCardDialog>();
    dialog->initialize(parent, std::move(ccards), selectedcard);
    const auto view = owner.m_view_tree;
    dialog->m_on_ok = [view, generation, epoch](std::optional<std::shared_ptr<::cw::header::CardHeader>> header) {
        const auto engine = ::cw::g_cwpy;
        if (!engine) return;
        engine->exec_func([engine, view, generation, epoch, header = std::move(header)](const auto&, const auto&) mutable {
            // 予約したネイティブのコールバックは、終了済みの所有者も拒否する。
            if (generation->load() == epoch && ::cw::g_cwpy == engine && engine->m_event &&
                view && view->enable_eventview() && engine->is_runningevent())
                engine->m_event->set_selectedcard(std::move(header));
            return ::cw::lib::Value{};
        });
    };
    (void)dialog->show_modal();
    });
    return ::cw::lib::Value{};
    });
    record(this, "open_selected_card_selector");
}

