void Debugger::OnStartEventTool(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (!::cw::g_cwpy || !::cw::g_cwpy->is_playingscenario() ||
        ::cw::g_cwpy->is_runningevent() ||
        (::cw::g_cwpy->is_battlestatus() && ::cw::g_cwpy->m_battle &&
         *::cw::g_cwpy->m_battle && !(*::cw::g_cwpy->m_battle)->is_ready()))
        return;
    auto parent = std::make_shared<::cw::lib::Window>();
    parent->title = "イベントの実行";
    if (arg_event && arg_event->native_handle)
        parent->native_handle = arg_event->native_handle;
    else if (const auto frame = m_parent.lock())
        parent->native_handle = frame->m_native_window_handle;
    auto dialog = std::make_shared<::cw::debug::event::EventListDialog>();
    ::cw::lib::String current_path = m__currentfpath;
    if (current_path.empty()) {
        if (const auto data = scenario_data()) {
            // Pythonはsdata.data.fpath、つまり現在表示中のエリア／バトルの
            // リソースを初期選択する。シナリオ本体のパスではない。
            if (data->m_data && *data->m_data)
                current_path = (*data->m_data)->m_fpath;
        }
    }
    dialog->initialize(parent, current_path, m__showhiddencards);
    if (!dialog->show_modal()) {
        return;
    }
    m__currentfpath = dialog->m_events ? dialog->m_events->get_currentfpath() : current_path;
    m__showhiddencards = dialog->m_showhiddencards;
    const auto selected = dialog->m_events ? dialog->m_events->get_selectedevent()
                                           : std::nullopt;
    if (!selected || !*selected)
        return;
    if (dialog->m_start_event) {
        const auto event = *selected;
        ::cw::g_cwpy->exec_func([event](const auto&, const auto&) {
            // 最初の開始要求がゲームスレッドへ届く前に、ネイ
            // ティブのボタン通知が重複する場合がある。 Python
            // 版がイベント開始時に操作を無効化するのと同じ
            // 制約を、実行境界でも確認し、 メッセージルー
            // プから重複イベントを再帰的に開始しない。
            // ただし is_runningevent()
            // は選択画面自身が残した予約入力も含むため
            // 使わず、 実際のEventInterface
            // スタックがある場合だけを重複開始とする。
            if (!::cw::g_cwpy ||
                (::cw::g_cwpy->m_event &&
                 ::cw::g_cwpy->m_event->get_nowrunningevent()))
                return ::cw::lib::Value{};
            try {
                event->start(false);
            } catch (const ::cw::battle::BattleError& error) {
                forward_debugger_battle_error(error);
            }
            return ::cw::lib::Value{};
        });
    } else if (m_view_tree) {
        m_view_tree->set_event(*selected, std::nullopt);
    }
    record(this, dialog->m_start_event ? "start_event" : "select_event");
}

