void Debugger::OnClearBreakpointTool(std::shared_ptr<::cw::lib::Window> arg_event)
{
    // Python版と同様、モーダル編集用に表を複製する前に、現在のシナ
    // リオをbreakpoint_tableへ保存する。 この小さい更新
    // を予約にすると、複製が先行して現在のシナリオを落とす場合がある。
    if (const auto data = scenario_data())
        data->save_breakpoints();
    const auto breakpoint_table = ::cw::g_cwpy
        ? ::cw::g_cwpy->m_breakpoint_table
        : std::map<std::tuple<::cw::lib::String, ::cw::lib::String>,
                   std::set<::cw::lib::String>>{};
    auto dialog = std::make_shared<::cw::debug::edit::BreakpointEditDialog>();
    const std::uintptr_t native_parent_handle = arg_event ? arg_event->native_handle : 0;
    dialog->initialize(m_self, breakpoint_table, native_parent_handle);
    const bool accepted = ::cw::debug::edit::show_modal(*dialog);
    if (accepted && ::cw::g_cwpy) {
        const auto parent = m_parent;
        ::cw::g_cwpy->exec_func([parent](const auto&, const auto&) {
            const auto data = scenario_data();
            if (!data || !::cw::g_cwpy || !::cw::g_cwpy->is_playingscenario())
                return ::cw::lib::Value{};
            const auto key = std::make_tuple(data->m_name, data->m_author);
            const auto found = ::cw::g_cwpy->m_breakpoint_table.find(key);
            static_cast<::cw::data::SystemData*>(data.get())->m_breakpoints =
                found == ::cw::g_cwpy->m_breakpoint_table.end()
                    ? std::set<::cw::lib::String>{} : found->second;
            const bool has_breakpoints = !::cw::g_cwpy->m_breakpoint_table.empty() ||
                !static_cast<::cw::data::SystemData*>(data.get())->m_breakpoints.empty();
            post_debugger_ui(parent, [has_breakpoints](Debugger& debugger) {
                set_tool(&debugger, id_value(g_ID_CLEAR_BREAKPOINT), has_breakpoints);
                // Pythonの view_tree.Refresh()
                // と同様、コールバックを予約した時点ではなく、 ゲー
                // ム側が新しい停止点集合を反映した後で描画を更新する。
                if (debugger.m_view_tree)
                    debugger.m_view_tree->m_paint_pending = true;
                redraw_debugger_presentation(debugger);
            });
            return ::cw::lib::Value{};
        });
    }
}

