void Debugger::refresh_tools()
{
    _refresh_tools();
}

void Debugger::_refresh_tools()
{
    if (!::cw::g_cwpy)
        return;
    ::cw::g_cwpy->exec_func([frame = m_parent](const auto&, const auto&) {
        if (!::cw::g_cwpy) return ::cw::lib::Value{};
        const auto data = system_data();
        const bool ydata = ::cw::g_cwpy->m_ydata.has_value() &&
                           *::cw::g_cwpy->m_ydata;
        const bool party = ydata && (*::cw::g_cwpy->m_ydata)->m_party &&
                           *(*::cw::g_cwpy->m_ydata)->m_party;
        const bool savedvariables = ydata && !(*::cw::g_cwpy->m_ydata)->m_saved_variables.empty();
        const bool savedjpdcimage = ydata && !(*::cw::g_cwpy->m_ydata)->m_savedjpdcimage.empty();
        const bool losted_sdata = ydata && (*::cw::g_cwpy->m_ydata)->m_losted_sdata &&
                                  *(*::cw::g_cwpy->m_ydata)->m_losted_sdata;
        const bool battle = ::cw::g_cwpy->m_battle.has_value() && *::cw::g_cwpy->m_battle;
        const bool battle_running = battle && (*::cw::g_cwpy->m_battle)->is_running();
        const bool runningevent = ::cw::g_cwpy->is_runningevent();
        const bool playingscenario = ::cw::g_cwpy->is_playingscenario();
        const bool battlestatus = ::cw::g_cwpy->is_battlestatus();
        const bool showingmessage = ::cw::g_cwpy->is_showingmessage();
        const bool paused = ::cw::g_cwpy->m_event && ::cw::g_cwpy->m_event->is_paused();
        const bool step = ::cw::g_cwpy->m_event && ::cw::g_cwpy->m_event->is_stepexec();
        const bool has_breakpoints = data && !data->m_breakpoints.empty();
        const bool has_breakpoint_table = !::cw::g_cwpy->m_breakpoint_table.empty();
        const bool showparty = ::cw::g_cwpy->m_is_showparty;
        const bool debug_skin = debug_skin_enabled();
        const bool editor_available = !::cw::dialog::is_all_mode() &&
                                       ::cw::g_cwpy->m_setting &&
                                       !::cw::g_cwpy->m_setting->m_editor.empty();

        post_debugger_ui(frame, [=](Debugger& debugger) {
            debugger.m_tool_enabled.clear();
            set_tool(&debugger, id_value(g_ID_COMPSTAMP), ydata);
            set_tool(&debugger, id_value(g_ID_GOSSIP), ydata);
            set_tool(&debugger, id_value(g_ID_SAVEDVARIABLES), savedvariables);
            set_tool(&debugger, id_value(g_ID_SAVEDJPDCIMAGE), savedjpdcimage);
            set_tool(&debugger, id_value(g_ID_MONEY), ydata);
            set_tool(&debugger, id_value(g_ID_CARD), ydata);
            set_tool(&debugger, id_value(g_ID_MEMBER), party);
            set_tool(&debugger, id_value(g_ID_COUPON), party);
            set_tool(&debugger, id_value(g_ID_LOAD_YADO), ydata);
            set_tool(&debugger, id_value(g_ID_INIT_VARIABLES), ydata);
            set_tool(&debugger, id_value(g_ID_PAUSE), true);
            set_tool(&debugger, id_value(g_ID_STATUS), playingscenario);
            set_tool(&debugger, id_value(g_ID_RECOVERY), playingscenario);
            set_tool(&debugger, id_value(g_ID_REDISPLAY), playingscenario);
            set_tool(&debugger, id_value(g_ID_PARTY_ENV), playingscenario);
            set_tool(&debugger, id_value(g_ID_EDITOR),
                     editor_available && (playingscenario || losted_sdata));
            set_tool(&debugger, id_value(g_ID_BREAK), playingscenario && !runningevent && !battlestatus);
            set_tool(&debugger, id_value(g_ID_SAVE), playingscenario && !runningevent && !battlestatus);
            set_tool(&debugger, id_value(g_ID_LOAD), playingscenario && !runningevent && !battlestatus);
            set_tool(&debugger, id_value(g_ID_ROUND), playingscenario && battlestatus && !runningevent);
            set_tool(&debugger, id_value(g_ID_BATTLE), playingscenario && !runningevent && (!battle || !battle_running));
            set_tool(&debugger, id_value(g_ID_PACK), playingscenario && !runningevent && (!battle || !battle_running));
            set_tool(&debugger, id_value(g_ID_FRIEND), playingscenario && !runningevent && (!battle || !battle_running));
            set_tool(&debugger, id_value(g_ID_INFO), playingscenario && !runningevent && (!battle || !battle_running));
            set_tool(&debugger, id_value(g_ID_AREA), playingscenario && !runningevent &&
                                                     (!battle || !battle_running));
            set_tool(&debugger, id_value(g_ID_STARTEVENT),
                     playingscenario && !runningevent && (!battle || !battle_running));
            set_tool(&debugger, id_value(g_ID_UPDATE), !runningevent && !battle_running &&
                                                     (playingscenario || debug_skin));
            set_tool(&debugger, id_value(g_ID_STOP), runningevent);
            const bool can_step = runningevent && (paused || (step && showingmessage));
            set_tool(&debugger, id_value(g_ID_STEPRETURN), can_step);
            set_tool(&debugger, id_value(g_ID_STEPOVER), can_step);
            set_tool(&debugger, id_value(g_ID_STEPIN), can_step);
            set_tool(&debugger, id_value(g_ID_BREAKPOINT), debugger.m_view_tree && debugger.m_view_tree->m_selectionitem.has_value() && playingscenario);
            set_tool(&debugger, id_value(g_ID_CLEAR_BREAKPOINT), has_breakpoints || has_breakpoint_table);
            set_tool(&debugger, id_value(g_ID_BGM), true);
            set_tool(&debugger, id_value(g_ID_SELECTION), runningevent);
            set_tool(&debugger, id_value(g_ID_SHOW_PARTY), runningevent && !showparty);
            set_tool(&debugger, id_value(g_ID_HIDE_PARTY), runningevent && showparty);
            set_tool(&debugger, id_value(g_ID_SELECTEDCARD), runningevent);
            if (::cw::g_cwpy && ::cw::g_cwpy->m_is_debuggerprocessing)
                for (auto& [id, enabled] : debugger.m_tool_enabled)
                    enabled = false;
            redraw_debugger_presentation(debugger);
        });
        return ::cw::lib::Value{};
    });
}

void Debugger::refresh_showpartytools()
{
    post_debugger_ui(m_parent, [](Debugger& debugger) {
        debugger._refresh_showpartytools();
        redraw_debugger_presentation(debugger);
    });
}

void Debugger::_refresh_showpartytools()
{
    if (!::cw::g_cwpy)
        return;
    const bool enabled = m_view_tree && m_view_tree->enable_eventview() &&
                         ::cw::g_cwpy->is_runningevent();
    set_tool(this, id_value(g_ID_SHOW_PARTY), enabled && !::cw::g_cwpy->m_is_showparty);
    set_tool(this, id_value(g_ID_HIDE_PARTY), enabled && ::cw::g_cwpy->m_is_showparty);
}

