    m_leftbarwidth = ::cw::dialog::is_all_mode() ? 24 : 44;
    m_lineheight = 16;
    m_maxwidth = 0;
    m_maxheight = 0;
    m_processing = false;
    m_scrollrate_x = 16;
    m_scrollrate_y = m_lineheight;
    m_selectionindex = -1;
    m_initialized = true;
    m_bound = false;
    m_has_focus = false;
    m_paint_pending = false;
    m_refresh_pending = false;
    m_client_width = 0;
    m_client_height = 0;
    m_view_start_x = 0;
    m_view_start_y = 0;
    m_virtual_width = 1;
    m_virtual_height = 1;
