void draw_debugger_scrollbar(::cw::dialog::DialogPresentation& result,
    const std::shared_ptr<::cw::lib::Surface>& surface,
    const ::cw::dialog::PresentationScrollAxis& axis,bool horizontal_axis,
    Integer x,Integer y,Integer bar,int id)
{
    namespace ui=::cw::lib::ui;
    using Action=::cw::dialog::DialogPresentationAction;
        const auto rect=[&](Integer offset,Integer length) {
            return horizontal_axis?::cw::lib::Rect{x+offset,y,length,bar}
                                  : ::cw::lib::Rect{x,y+offset,bar,length};
        };
        const auto bounds=rect(0,axis.length);
        ui::fill_rect(surface,bounds,{232,232,232,255});
        for(const auto offset:{Integer{0},axis.length-axis.arrow}) {
            const auto button=rect(offset,axis.arrow);
            ui::fill_rect(surface,button,{240,240,240,255});
            ui::draw_raised_border(surface,button);
            const auto center=offset+axis.arrow/2;
            for(Integer d=0;d<4 && axis.arrow>=8 && bar>=8;++d) {
                const auto p=center+(offset==0?-2+d:2-d);
                ui::fill_rect(surface,horizontal_axis
                    ?::cw::lib::Rect{x+p,y+bar/2-d,1,2*d+1}
                    : ::cw::lib::Rect{x+bar/2-d,y+p,2*d+1,1},{64,64,64,255});
            }
        }
        const auto thumb=rect(axis.thumb_start,axis.thumb);
        ui::fill_rect(surface,thumb,{192,192,192,255});
        ui::draw_sunken_border(surface,thumb);
        result.controls.push_back({Action::Auxiliary,id,static_cast<float>(bounds.x),static_cast<float>(bounds.y),
            static_cast<float>(bounds.width),static_cast<float>(bounds.height),true,true,
            horizontal_axis?"横スクロール":"縦スクロール"});
}


bool DebuggerListViewport::owns(int id) const {
    return id==horizontal_id || id==vertical_id ||
        (resize_base!=-1 && id<=resize_base && id>resize_base-column_count);
}
void DebuggerListViewport::cancel() noexcept {
    resizing=-1;horizontal.cancel();vertical.cancel();
}
bool DebuggerListViewport::repeat_due() const noexcept {
    return horizontal.repeat_due() || vertical.repeat_due();
}
::cw::dialog::DialogPresentation DebuggerListViewport::render(::cw::lib::Size size,
    const std::vector<::cw::lib::String>& columns,const std::vector<Integer>& widths,
    Integer count,Integer selected,bool focused,Integer& first_row,
    const Text& text,const Icon& icon,bool auto_width)
{
    namespace ui=::cw::lib::ui;
    const auto metrics=debugger_logical_metrics();
    const auto font=metrics.font;
    const Integer width=(std::max<Integer>)(1,size.width),height=(std::max<Integer>)(1,size.height);
    header_height=columns.empty()?0:(std::min)(height,(std::max<Integer>)(20,metrics.line_height+6));
    row_height=(std::max<Integer>)(18,metrics.line_height+4);
    row_count=(std::max<Integer>)(0,count);column_count=static_cast<Integer>(widths.size());
    Integer total=0;
    for(auto w:widths) total+=(std::max<Integer>)(0,w);
    const Integer bar=(std::max<Integer>)(0,(std::min<Integer>)(16,(std::min)(width-1,height-header_height-1)));
    bar_thickness=bar;
    bool h=false,v=false;
    for(int pass=0;pass<3;++pass) {
        visible_rows=(std::max<Integer>)(1,(height-header_height-(h?bar:0))/row_height);
        v=bar>0 && count>visible_rows;
        h=!auto_width && bar>0 && total>width-(v?bar:0);
    }
    client_width=width-(v?bar:0);client_height=height-(h?bar:0);
    visible_rows=(std::max<Integer>)(1,(client_height-header_height)/row_height);
    horizontal.configure(h?client_width:0,client_width,auto_width?client_width:total,16,horizontal.position);
    vertical.configure(v?client_height-header_height:0,visible_rows,count,1,first_row);
    horizontal.tick();vertical.tick();first_row=vertical.position;
    auto surface=std::make_shared<::cw::lib::Surface>();
    surface->size={width,height};surface->rgba.resize(static_cast<std::size_t>(width*height*4));
    ui::fill_rect(surface,{0,0,width,height},{255,255,255,255});
    ::cw::dialog::DialogPresentation result;result.surface=surface;
    const auto cell=[&](const ::cw::lib::String& value,Integer x,Integer y,Integer w,Integer cell_height,
                        ::cw::lib::Color background,std::tuple<int,int,int> ink,
                        const std::shared_ptr<::cw::lib::Surface>& bitmap,bool icon_column) {
        const Integer left=(std::max<Integer>)(0,x),right=(std::min)(client_width,x+w);
        const Integer bottom=(std::min)(client_height,y+cell_height);
        if(right<=left || bottom<=y) return;
        auto part=std::make_shared<::cw::lib::Surface>();part->size={right-left,bottom-y};
        part->rgba.resize(static_cast<std::size_t>(part->size.width*part->size.height*4));
        ui::fill_rect(part,{0,0,part->size.width,part->size.height},background);
        if(bitmap) ui::blend_surface(part,bitmap,x-left+2,(cell_height-16)/2,16,16);
        ui::draw_label(part,value,x-left+(icon_column?21:4),(cell_height-font.pixels)/2,
            font.pixels,font.bold,ink,font.face);
        ui::blend_surface(surface,part,left,y);
    };
    if(header_height) {
        Integer x=-horizontal.position;
        for(std::size_t col=0;col<widths.size();++col) {
            const Integer w=(std::max<Integer>)(0,widths[col]);
            cell(col<columns.size()?columns[col]:"",x,0,w,header_height,{255,255,255,255},{0,0,0},{},false);
            x+=w;
            if(x>=0 && x<client_width) ui::fill_rect(surface,{x,0,1,header_height},{210,210,210,255});
        }
        ui::fill_rect(surface,{0,header_height-1,client_width,1},{210,210,210,255});
    }
    for(Integer row=first_row,y=header_height;row<count && y<client_height;++row,y+=row_height) {
        const bool chosen=row==selected;
        const auto background=chosen?(focused?::cw::lib::Color{0,120,215,255}:
            ::cw::lib::Color{220,220,220,255}): ::cw::lib::Color{255,255,255,255};
        const auto ink=chosen&&focused?std::tuple{255,255,255}:std::tuple{0,0,0};
        const Integer rh=(std::min)(row_height,client_height-y);
        ui::fill_rect(surface,{0,y,client_width,rh},background);
        Integer x=-horizontal.position;
        for(Integer col=0;col<column_count;++col) {
            const Integer w=auto_width?client_width:(std::max<Integer>)(0,widths[static_cast<std::size_t>(col)]);
            cell(text(row,col),x,y,w,row_height,background,ink,col==0?icon(row):nullptr,col==0);
            x+=w;
        }
        const auto name=text(row,0);
        result.controls.push_back({::cw::dialog::DialogPresentationAction::Select,row_base+static_cast<int>(row),
            0.0F,static_cast<float>(y),static_cast<float>(client_width),static_cast<float>(rh),true,false,
            name,column_count>1?name+": "+text(row,1):name});
    }
    if(h) draw_debugger_scrollbar(result,surface,horizontal,true,0,client_height,bar,horizontal_id);
    if(v) draw_debugger_scrollbar(result,surface,vertical,false,client_width,header_height,bar,vertical_id);
    if(header_height && resize_base!=-1) {
        Integer x=-horizontal.position;
        for(Integer col=0;col<column_count;++col) {
            x+=(std::max<Integer>)(0,widths[static_cast<std::size_t>(col)]);
            const auto left=(std::max<Integer>)(0,x-3),right=(std::min)(client_width,x+3);
            if(right>left) result.controls.push_back({::cw::dialog::DialogPresentationAction::Auxiliary,
                resize_base-static_cast<int>(col),static_cast<float>(left),0,
                static_cast<float>(right-left),static_cast<float>(header_height),true,true,
                col<static_cast<Integer>(columns.size())?columns[static_cast<std::size_t>(col)]:"",
                "ドラッグで列幅を変更・ダブルクリックで内容に合わせます。",true});
        }
    }
    return result;
}
void DebuggerListViewport::pointer(int id,float x,float y,bool pressed,
    std::vector<Integer>& widths,Integer& first_row)
{
    if(id==horizontal_id) {
        horizontal.pointer(x,pressed,::cw::dialog::PresentationScrollAxis::Clock::now(),
            y>=client_height && y<client_height+bar_thickness);
    } else if(id==vertical_id) {
        vertical.pointer(y-static_cast<float>(header_height),pressed,
            ::cw::dialog::PresentationScrollAxis::Clock::now(),x>=client_width && x<client_width+bar_thickness);
        first_row=vertical.position;
    } else if(resize_base!=-1 && id<=resize_base && id>resize_base-static_cast<int>(widths.size())) {
        const int col=resize_base-id;
        if(resizing<0) {
            if(!pressed) return;
            resizing=col;resize_x=x;resize_width=widths[static_cast<std::size_t>(col)];
        }
        if(resizing==col && std::isfinite(x))
            widths[static_cast<std::size_t>(col)]=static_cast<Integer>(std::llround(
                std::clamp(static_cast<double>(resize_width)+x-resize_x,0.0,1000000.0)));
        if(!pressed) resizing=-1;
    }
}
bool DebuggerListViewport::autosize(int id,std::vector<Integer>& widths,
    const std::vector<::cw::lib::String>& columns,Integer count,const Text& text)
{
    if(resize_base==-1 || id>resize_base || id<=resize_base-static_cast<int>(widths.size())) return false;
    const int col=resize_base-id;
    const auto font=debugger_logical_metrics().font;
    Integer width=col<static_cast<int>(columns.size())?
        ::cw::lib::ui::label_width(columns[static_cast<std::size_t>(col)],font.pixels,font.bold,font.face)+8:8;
    for(Integer row=0;row<count;++row) width=(std::max)(width,
        ::cw::lib::ui::label_width(text(row,col),font.pixels,font.bold,font.face)+(col==0?25:8));
    widths[static_cast<std::size_t>(col)]=width;
    return true;
}
bool DebuggerListViewport::navigate(::cw::dialog::DialogPresentationKey key,
    Integer& selected,Integer& first_row) const
{
    using Key=::cw::dialog::DialogPresentationKey;
    if(key!=Key::Up && key!=Key::Down && key!=Key::Home && key!=Key::End &&
       key!=Key::PageUp && key!=Key::PageDown) return false;
    if(!row_count) {selected=-1;first_row=0;return true;}
    if(key==Key::Home) selected=0;
    else if(key==Key::End) selected=row_count-1;
    else if(selected<0 || selected>=row_count) selected=0;
    else selected+=key==Key::Up?-1:key==Key::Down?1:key==Key::PageUp?-visible_rows:visible_rows;
    selected=std::clamp(selected,Integer{0},row_count-1);
    if(selected<first_row) first_row=selected;
    if(selected>=first_row+visible_rows) first_row=selected-visible_rows+1;
    first_row=std::clamp(first_row,Integer{0},(std::max<Integer>)(0,row_count-visible_rows));
    return true;
}

::cw::dialog::DialogPresentation EventView::event_presentation(
    ::cw::lib::Size viewport, const std::set<::cw::lib::String>& breakpoints)
{
    namespace ui = ::cw::lib::ui;
    using Action = ::cw::dialog::DialogPresentationAction;
    const auto make_surface = [](Integer width, Integer height, ::cw::lib::Color color) {
        auto result = std::make_shared<::cw::lib::Surface>();
        result->size = {(std::max<Integer>)(1, width), (std::max<Integer>)(1, height)};
        result->rgba.resize(static_cast<std::size_t>(result->size.width * result->size.height) * 4);
        ui::fill_rect(result, {0, 0, result->size.width, result->size.height}, color);
        return result;
    };
    // 境界を持つ別々のレイヤーで、wx の固定欄とコンテントのクリッピングを再現
    // する。 他のペイン、ツールバー、ステータスバーには描画をはみ出させない。
    const auto width = (std::max<Integer>)(1, viewport.width);
    const auto full_height = (std::max<Integer>)(1, viewport.height);
    // ALL仕様: ブレークポイントは行の色で示し、赤丸用の20pxを行番号欄から除く。
    const bool all_ui = ::cw::dialog::is_all_mode();
    const auto gutter = (std::min<Integer>)(width,
        (std::max<Integer>)(all_ui ? 24 : 44, m_leftbarwidth) + 1);
    const auto bar = (std::max<Integer>)(0,(std::min<Integer>)(16,
        (std::min)(full_height-1,width-gutter-1)));
    bool vertical=false, horizontal=false;
    // 片方のスクロールバーが反対方向の表示領域を狭めるため、両方必要になる場合がある。
    for(int pass=0;pass<3;++pass) {
        vertical=bar>0 && m_virtual_height>full_height-(horizontal?bar:0);
        horizontal=bar>0 && m_virtual_width>width-gutter-(vertical?bar:0);
    }
    const auto height=full_height-(horizontal?bar:0);
    const auto body_width=(std::max<Integer>)(1,width-gutter-(vertical?bar:0));
    const auto font = debugger_logical_metrics().font;
    const auto line = (std::max<Integer>)(1, m_lineheight);
    auto surface = make_surface(width, full_height, {240, 240, 240, 255});
    auto body = make_surface(body_width, height, {255, 255, 255, 255});
    m_client_width = body_width;
    m_client_height = height;
    m_scroll_gutter = gutter;
    m_scrollbar_thickness = bar;
    m_horizontal_scroll.configure(horizontal?body_width:0,body_width,m_virtual_width,m_scrollrate_x,m_view_start_x);
    m_vertical_scroll.configure(vertical?height:0,height,m_virtual_height,line,m_view_start_y);
    m_horizontal_scroll.tick();
    m_vertical_scroll.tick();
    m_view_start_x=m_horizontal_scroll.position;
    m_view_start_y=m_vertical_scroll.position;
    const auto top = m_view_start_y;
    const auto left = m_view_start_x;
    ::cw::dialog::DialogPresentation result;
    result.route = "DebuggerEventView";
    result.surface = surface;
    const auto label = [&](const auto& target, const ::cw::lib::String& text,
                           Integer x, Integer y, std::tuple<Integer, Integer, Integer> color) {
        ui::draw_label(target, text, x, y, font.pixels, font.bold, color, font.face);
    };
    const auto circle = [&](const auto& target, Integer cx, Integer cy, Integer radius,
                            ::cw::lib::Color outline, bool hollow) {
        for (Integer y = (std::max<Integer>)(0, cy - radius); y <= cy + radius && y < height; ++y)
            for (Integer x = (std::max<Integer>)(0, cx - radius); x <= cx + radius && x < target->size.width; ++x) {
                const auto d = (x-cx)*(x-cx)+(y-cy)*(y-cy);
                if (d <= radius*radius)
                    ui::fill_rect(target, {x,y,1,1}, hollow && d < (radius-2)*(radius-2)
                        ? ::cw::lib::Color{255,255,255,255} : outline);
            }
    };
    const auto line_to = [&](Integer x, Integer y1, Integer y2) {
        if (y2 >= y1) ui::fill_rect(body, {x-2, y1, 4, y2-y1+1}, {192,192,192,255});
    };
    const auto arc = [&](Integer x, Integer y, Integer rw, Integer rh) {
        // wx.DrawArc の左下の四分円で、親の縦線から字下げした子へ接続する。
        const double thickness = 2.0 / static_cast<double>((std::min)(rw,rh));
        for (Integer py = (std::max<Integer>)(0,y); py <= y+rh+2 && py < height; ++py)
            for (Integer px = (std::max<Integer>)(0,x-2); px <= x+rw && px < body_width; ++px) {
                const double dx = static_cast<double>(px-x-rw)/rw;
                const double dy = static_cast<double>(py-y)/rh;
                if (std::abs(std::sqrt(dx*dx+dy*dy)-1.0) <= thickness)
                    ui::fill_rect(body,{px,py,1,1},{192,192,192,255});
            }
    };
    if (m_itemlist.empty()) {
        label(body,"ここに実行中のイベントツリーが表示されます。",10,5,{0,0,0});
        label(body,"ヒント: ダブルクリックかEnterキー押下で任意の",10,10+font.pixels,{0,0,0});
        label(body,"イベントコンテントを実行できます。",10,10+font.pixels*2,{0,0,0});
    }
    for (std::size_t row=0; row<m_itemlist.size(); ++row) {
        const auto& item=m_itemlist[row];
        const auto found=m_itemstates.find(item);
        if (!item || found==m_itemstates.end()) continue;
        const auto& state=found->second;
        const auto y=state.y-top;
        if (y>=height) break;
        if (y+state.height<=0) continue;
        const auto number=std::to_string(row+1);
        label(surface,number,gutter-(all_ui ? 3 : 23)-ui::label_width(number,font.pixels,font.bold,font.face),
            y+(line-font.pixels)/2,{64,64,64});
        if (!state.parent && row>0) ui::fill_rect(body,{0,y,body_width,1},{128,128,128,255});
        const bool breakpoint = breakpoints.contains(state.cwxpath);
        if (breakpoint) {
            if (!all_ui) circle(surface,gutter-12,y+line/2,6,{128,0,0,255},false);
            ui::fill_rect(body,{0,y,body_width,line},{255,240,232,255});
        }
        const bool active=m_activeitem && *m_activeitem==item;
        const bool selected=m_selectionitem && *m_selectionitem==item;
        if (active) ui::fill_rect(body,{0,y,body_width,line},all_ui
            ? ::cw::lib::Color{255,245,190,255} : ::cw::lib::Color{255,192,192,255});
        if (selected) {
            if (!active) ui::fill_rect(body,{0,y,body_width,line},all_ui
                ? ::cw::lib::Color{232,240,255,255} : ::cw::lib::Color{255,240,240,255});
            const auto border=all_ui ? ::cw::lib::Color{96,128,192,255} : ::cw::lib::Color{255,128,128,255};
            ui::fill_rect(body,{0,y,body_width,1},border);
            ui::fill_rect(body,{0,y+line-1,body_width,1},border);
        }
        // ALL にはブレークポイントの点がないため、選択中や実行中でも赤い行を識
        // 別できるようにする。 単に選択しただけの行を停止位置のように表示しない。
        if (all_ui && breakpoint) {
            ui::fill_rect(body,{0,y,body_width,line},{255,192,192,255});
            ui::fill_rect(body,{0,y,body_width,1},{220,64,64,255});
            ui::fill_rect(body,{0,y+line-1,body_width,1},{220,64,64,255});
        }
        const auto hit_top=(std::max<Integer>)(0,y);
        const auto hit_bottom=(std::min<Integer>)(height,y+state.height);
        result.controls.push_back({Action::Auxiliary,DebuggerPresentationBreakpointBase+static_cast<int>(row),
            0.0F,static_cast<float>(hit_top),static_cast<float>(gutter),static_cast<float>(hit_bottom-hit_top),
            true,false,"ブレークポイント","ブレークポイントを切り替えます。"});
        if (gutter<width) result.controls.push_back({Action::Select,20000+static_cast<int>(row),
            static_cast<float>(gutter),static_cast<float>(hit_top),static_cast<float>(body_width),
            static_cast<float>(hit_bottom-hit_top),true,false,
            state.text+(active?" // ACTIVE!":""),state.text});
    }
    // 接続線はアイコンとテキストより先に描画し、親が画面外にある縦線も含め
    // る。 ContentsLine は最初に表示されるコンテントを示す。
    const Integer iw=(std::max<Integer>)(1,m_scrollrate_x);
    std::vector<std::pair<Integer,Integer>> circles;
    for (const auto& item:m_itemlist) {
        const auto found=m_itemstates.find(item);
        if (found==m_itemstates.end()) continue;
        const auto& state=found->second;
        const auto cx=state.x-left+iw/2-1;
        const auto cy=state.y-top+line/2;
        if (state.y-top>=height) break;
        if (state.nextdata.empty()) {
            const auto bottom=cy+line-4;
            if (bottom<0) continue;
            line_to(cx,cy,bottom);
            ui::fill_rect(body,{cx-5,bottom-2,10,4},{192,192,192,255});
        } else for (auto child:state.nextdata) {
            if (child && child->m_tag=="ContentsLine")
                child=child->m_children.empty()?nullptr:child->m_children.front();
            const auto child_item=m_items.find(child);
            if (child_item==m_items.end()) continue;
            const auto child_state=m_itemstates.find(child_item->second);
            if (child_state==m_itemstates.end()) continue;
            const auto& next=child_state->second;
            if (next.y-top+line<0) continue;
            if (next.x==state.x) line_to(cx,cy,next.y-top+line/2);
            else {
                const auto bottom=next.y-top-line/2;
                if (cy<bottom) {line_to(cx,cy,bottom);circles.emplace_back(cx,bottom+2);}
                arc(cx,bottom,iw,line);
            }
        }
    }
    for (const auto [x,y]:circles) circle(body,x,y,6,{192,192,192,255},true);
    for (const auto& item:m_itemlist) {
        const auto found=m_itemstates.find(item);
        if (!item || found==m_itemstates.end()) continue;
        const auto& state=found->second;
        const auto y=state.y-top;
        if (y>=height) break;
        if (y+line<=0) continue;
        const auto x=state.x-left-1;
        std::shared_ptr<::cw::lib::Surface> icon;
        if (const auto* value=std::get_if<::cw::lib::ObjectPtr>(&item->m_image.storage()))
            icon=std::dynamic_pointer_cast<::cw::lib::Surface>(*value);
        if (icon) ui::blend_surface(body,icon,x,y); // アイコン本来のピクセル寸法を使い、ゲームの拡大率を適用しない。
        const bool active=m_activeitem && *m_activeitem==item;
        const auto text=state.text+(active?" // ACTIVE!":"");
        label(body,text,x+(icon?icon->size.width:0)+2,y+(line-font.pixels)/2,
            active?std::tuple<Integer,Integer,Integer>{255,0,0}:std::tuple<Integer,Integer,Integer>{0,0,0});
    }
    if (gutter<width) ui::blend_surface(surface,body,gutter,0);
    ui::fill_rect(surface,{gutter-1,0,1,height},{128,128,128,255});
    // スクロールバーは行コントロールと固定行番号欄の外側に最後に描画する。 OS
    // 固有の子ウィジェットではなく、共通の CPU 描画 UI を使う。
    if(horizontal) ui::fill_rect(surface,{0,height,width,bar},{240,240,240,255});
    if(horizontal) draw_debugger_scrollbar(result,surface,m_horizontal_scroll,true,gutter,height,bar,DebuggerPresentationEventHorizontal);
    if(vertical) draw_debugger_scrollbar(result,surface,m_vertical_scroll,false,width-bar,0,bar,DebuggerPresentationEventVertical);
    return result;
}

void EventView::event_scroll_pointer(int index,float x,float y,bool pressed)
{
    if(index==DebuggerPresentationEventHorizontal) {
        m_vertical_scroll.cancel();
        m_horizontal_scroll.pointer(x-static_cast<float>(m_scroll_gutter),pressed,
            ::cw::dialog::PresentationScrollAxis::Clock::now(),
            y>=m_client_height && y<m_client_height+m_scrollbar_thickness);
        m_view_start_x=m_horizontal_scroll.position;
    } else if(index==DebuggerPresentationEventVertical) {
        m_horizontal_scroll.cancel();
        m_vertical_scroll.pointer(y,pressed,::cw::dialog::PresentationScrollAxis::Clock::now(),
            x>=m_scroll_gutter+m_client_width && x<m_scroll_gutter+m_client_width+m_scrollbar_thickness);
        m_view_start_y=m_vertical_scroll.position;
    }
}
void EventView::event_scroll_cancel() noexcept
{
    m_horizontal_scroll.cancel();
    m_vertical_scroll.cancel();
}
bool EventView::event_scroll_repeat_due() const noexcept
{
    return m_horizontal_scroll.repeat_due() || m_vertical_scroll.repeat_due();
}

bool EventView::enable_eventview()
{
    return ::cw::g_cwpy && (::cw::g_cwpy->is_playingscenario() || debug_skin_enabled());
}

std::optional<std::shared_ptr<::cw::debug::debugger::EventViewItem>> EventView::get_item(std::tuple<::cw::lib::Integer, ::cw::lib::Integer> arg_pos)
{
    const auto index = get_index(std::move(arg_pos));
    if (index < 0 || static_cast<std::size_t>(index) >= m_itemlist.size())
        return std::nullopt;
    return m_itemlist[static_cast<std::size_t>(index)];
}

::cw::lib::Integer EventView::get_index(std::tuple<::cw::lib::Integer, ::cw::lib::Integer> arg_pos)
{
    const auto y = std::get<1>(arg_pos);
    std::size_t first = 0;
    std::size_t last = m_itemlist.size();
    while (first < last) {
        const auto middle = first + (last - first) / 2;
        const auto state = m_itemstates.find(m_itemlist[middle]);
        if (state == m_itemstates.end()) {
            first = middle + 1;
            continue;
        }
        if (y < state->second.y) {
            last = middle;
        } else if (state->second.y + state->second.height <= y) {
            first = middle + 1;
        } else {
            return static_cast<::cw::lib::Integer>(middle);
        }
    }
    // 計測した行矩形の外側は、この保持型キャンバスでは項目に当たらないため、項目なしを示す値を返す。
    return -1;
}

void EventView::set_selectionitem(std::optional<std::shared_ptr<::cw::debug::debugger::EventViewItem>> arg_item)
{
    // ツリー再構築後も、選択項目と現在の行番号を同期させる。
    m_selectionitem = std::move(arg_item);
    m_selectionindex = -1;
    if (m_selectionitem && *m_selectionitem) {
        for (std::size_t index = 0; index < m_itemlist.size(); ++index) {
            if (m_itemlist[index] == *m_selectionitem) {
                m_selectionindex = static_cast<::cw::lib::Integer>(index);
                break;
            }
        }
    }
    if (const auto parent = m_parent.lock())
        parent->refresh_breakpointtool();
    m_paint_pending = true;
}

void EventView::update_selection_status()
{
    m_status_text.clear();
    if (!m_selectionitem || !*m_selectionitem) return;
    const auto state = m_itemstates.find(*m_selectionitem);
    if (state == m_itemstates.end()) return;
    m_status_text = state->second.text;
    // Python のステータスバーと同様、分岐の見出しではなく content.get_status()
    // を表示する。 見出しを使うのは、不完全または未接続のモデル行だけとする。
    if (m_current_event && *m_current_event && state->second.content) {
        const auto content = ::cw::content::get_content(state->second.content);
        if (content) m_status_text = content->get_status(m_current_event);
    }
}

void EventView::switch_breakpoint(std::optional<std::shared_ptr<::cw::debug::debugger::EventViewItem>> arg_item)
{
    if (!enable_eventview())
        return;
    {
        const auto item = arg_item && *arg_item ? *arg_item : (m_selectionitem ? *m_selectionitem : nullptr);
        if (!item)
            return;
        const auto state = m_itemstates.find(item);
        if (state == m_itemstates.end() || state->second.cwxpath.empty())
            return;
        const auto debugger = m_parent.lock();
        if (!debugger || !::cw::g_cwpy)
            return;
        const auto path = state->second.cwxpath;
        auto data = scenario_data();
        if (!data)
            data = std::dynamic_pointer_cast<::cw::data::ScenarioData>(system_data());
        if (!data)
            return;
        auto* system = static_cast<::cw::data::SystemData*>(data.get());
        const auto breakpoint = system->m_breakpoints.find(path);
        if (breakpoint == system->m_breakpoints.end())
            system->m_breakpoints.insert(path);
        else
            system->m_breakpoints.erase(breakpoint);

        // Python はデバッガー UI で sdata.breakpoints
        // を同期的に変更してから再描画する。 変更をゲームスレッドに予約す
        // ると、停止処理が先にイベントとツリーを消去し、 遅れたブレークポイ
        // ント処理が消去済みツリーへのポインターで再描画してしまう。 変更と
        // 表示更新を一つの UI 操作として処理する。 Py の refresh_clearbreakpointtool
        // は他のシナリオに保存した印も含むため、現
        // 在の最後の印を消しても、それらを隠さない。
        const bool has_breakpoints = !::cw::g_cwpy->m_breakpoint_table.empty() ||
                                     !system->m_breakpoints.empty();
        m_paint_pending = true;
        set_tool(debugger.get(), id_value(g_ID_CLEAR_BREAKPOINT), has_breakpoints);
        redraw_debugger_presentation(*debugger);
    }}

void EventView::click_row(const std::shared_ptr<EventViewItem>& item)
{
    // ネイティブ版の拡張として、行本体のクリックでもブレークポイントを切り替える。Py
    // では本体は選択のみで、切り替えは左端の欄に限る。 この操作方針は ALL
    // と単体版のネイティブイベント、Presentation の双方で共通にする。
    set_selectionitem(item);
    switch_breakpoint(item);
    update_selection_status();
}

void EventView::OnLeftDown(std::shared_ptr<::cw::lib::Window> arg_event)
{
    {
        m_has_focus = true;
        const auto x = arg_event ? arg_event->bounds.x : 0;
        const auto y = (arg_event ? arg_event->bounds.y : 0) + m_view_start_y;
        if (arg_event && arg_event->bounds.width > 0)
            m_client_width = arg_event->bounds.width;
        if (arg_event && arg_event->bounds.height > 0)
            m_client_height = arg_event->bounds.height;
        if (x < m_leftbarwidth) {
            switch_breakpoint(get_item({x + m_view_start_x, y}));
            return;
        }
        const auto index = get_index({x + m_view_start_x, y});
        if (index < 0)
            return;
        click_row(m_itemlist[static_cast<std::size_t>(index)]);
        m_paint_pending = true;
        if (const auto parent = m_parent.lock())
            redraw_debugger_presentation(*parent);
    }}

void EventView::OnDClick(std::shared_ptr<::cw::lib::Window> arg_event)
{
    {
        m_has_focus = true;
        const auto x = arg_event ? arg_event->bounds.x : 0;
        if (x < m_leftbarwidth)
            return;
        const auto y = (arg_event ? arg_event->bounds.y : 0) + m_view_start_y;
        const auto item = get_item({x + m_view_start_x, y});
        if (item && *item)
            set_activeitem(*item);
    }}

void EventView::set_activeitem(std::shared_ptr<::cw::debug::debugger::EventViewItem> arg_item)
{
    if (!arg_item)
        return;
    const auto state = m_itemstates.find(arg_item);
    if (state == m_itemstates.end())
        return;
    auto data = state->second.content;
    if (!state->second.parent) {
        if (state->second.nextdata.empty())
            return;
        data = state->second.nextdata.front();
    }
    if (!data)
        return;
    // 保持型 UI では Py と異なり、アクティブ化通知を待たず、予約
    // したゲーム側の切り替えより先にクリックされた行を公開する。 これに
    // より操作要求を直ちに表示できる。切り替え中もそのツリーのローカル
    // 変数を表示するため、 下の変数取得では Py が既定とする実行中
    // の Event ではなく、選択した Event を明示的に使う。
    m_activeitem = arg_item;
    m_current_content = data;
    if (::cw::g_cwpy) {
        const auto event = m_current_event;
        ::cw::g_cwpy->exec_func([data, event](const auto&, const auto&) {
            if (::cw::g_cwpy && ::cw::g_cwpy->m_event)
                ::cw::g_cwpy->m_event->set_curcontent(data, event);
            return ::cw::lib::Value{};
        });
    }
    if (const auto parent = m_parent.lock(); parent && parent->m_view_var)
        parent->m_view_var->refresh_variablelist(m_current_event);
    m_paint_pending = true;
}

void EventView::OnKeyDown(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (m_itemlist.empty())
        return;
    {
        constexpr ::cw::lib::Integer left = 37;
        constexpr ::cw::lib::Integer up = 38;
        constexpr ::cw::lib::Integer right = 39;
        constexpr ::cw::lib::Integer down = 40;
        const auto keycode = arg_event ? arg_event->id : 0;
        const bool previous = keycode == left || keycode == up;
        const bool next = keycode == right || keycode == down;
        if (!previous && !next)
            return;
        ::cw::lib::Integer index = m_selectionindex;
        if (!m_selectionitem || !*m_selectionitem || index < 0 ||
            index >= static_cast<::cw::lib::Integer>(m_itemlist.size()))
            index = 0;
        else if (previous && index > 0)
            --index;
        else if (next && index + 1 < static_cast<::cw::lib::Integer>(m_itemlist.size()))
            ++index;
        set_selectionitem(m_itemlist[static_cast<std::size_t>(index)]);
        show_item(*m_selectionitem);
        update_selection_status();
        if (const auto parent = m_parent.lock())
            redraw_debugger_presentation(*parent);
    }}

void EventView::OnKeyUp(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (m_itemlist.empty() || !m_selectionitem || !*m_selectionitem)
        return;
    const auto keycode = arg_event ? arg_event->id : 0;
    if ((keycode == 13 || keycode == 32) && (!m_activeitem || *m_activeitem != *m_selectionitem))
        set_activeitem(*m_selectionitem);
}

void EventView::show_item(std::shared_ptr<::cw::debug::debugger::EventViewItem> arg_item)
{
    if (!arg_item)
        return;
    const auto state = m_itemstates.find(arg_item);
    if (state == m_itemstates.end())
        return;
    // 行は計測済みのピクセル境界を持つため、行単位に丸めず、行全体が見える位置まで保持型キャンバスをスクロールする。
    const auto y = state->second.y;
    const auto height = state->second.height;
    const auto client_height = std::max<::cw::lib::Integer>(m_client_height, m_lineheight);
    if (y < m_view_start_y)
        m_view_start_y = y;
    else if (m_view_start_y + client_height <= y + height)
        m_view_start_y = std::max<::cw::lib::Integer>(0, y + height - client_height);
    m_view_start_y = std::clamp(m_view_start_y, ::cw::lib::Integer{0}, std::max<::cw::lib::Integer>(0, m_virtual_height - client_height));
    // 既存項目のスクロールや選択ではイベントツリーの構造は変わらない。 こ
    // こでネイティブの TreeView を再構築すると選択が失われ、分岐
    // 行がちらつくため、Python と同様に既存の表示だけを再描画する。
    m_paint_pending = true;
    if (const auto parent = m_parent.lock())
        redraw_debugger_presentation(*parent);
}

// ネイティブ版のスタック末尾の取得は、行の変更有無とは独立している。同じコンテント
// の更新でもスタックの内容は変わり得る。 Py は同じコンテントなら早期に戻り、
// スタックを更新しない。また、コンテントが消えた際、Py は current_content
// だけを消すが、 ネイティブ版は保持している強調表示を除くため、アクティブ行
// も消す。これらは保持型の表示方式による違いである。 processing は
// 下の UI への反映だけを保護し、Py のように予約後の待機まで覆わない。
// ゲーム側のスナップショット取得処理から UI 所有のフラグは変更しない。
void EventView::refresh_activeitem()
{
    const auto debugger=m_parent.lock();
    if (!debugger || !::cw::g_cwpy) return;
    bool called_on_worker=false;
    {
        std::scoped_lock lock(::cw::g_cwpy->m_game_exec_mutex);
        called_on_worker=::cw::g_cwpy->m_game_thread_id==std::this_thread::get_id();
    }
    if (called_on_worker) {
        // Py はこのメソッドを UI スレッドで実行する。ネイティブ版のワーカ
        // ー通知はまず共通 UI 境界を通し、 選択イベントの状態を所有スレッ
        // ドだけで読み取ってから、下のゲーム側スナップショット取得を実行する。
        post_debugger_ui(debugger->m_parent,[expected=this](Debugger& owner) {
            if (owner.m_view_tree && owner.m_view_tree.get()==expected)
                owner.m_view_tree->refresh_activeitem();
        });
        return;
    }
    if (!m_initialized) return;
    const auto status_event=m_current_event;
    const auto previous_content=m_current_content;
    const auto parent=debugger->m_parent;
    const auto generation=debugger->m_stack_epoch;
    const auto stack_epoch=generation->load();
    // refresh_all() からも UI スレッド上で呼ばれる。どちらの場合も取得はワーカーで
    // 行い、 その処理から UI 所有の Debugger や EventView を参照しない。
    const auto collect=[parent,generation,stack_epoch,status_event,previous_content,expected=this] {
        if (!::cw::g_cwpy || !::cw::g_cwpy->m_event) return;
        const auto event = ::cw::g_cwpy->m_event->get_event();
        const auto nowrunning = ::cw::g_cwpy->m_event->get_nowrunningevent();
        std::optional<std::shared_ptr<::cw::data::CWPyElement>> content;
        if (event && *event)
            content = (*event)->m_cur_content;
        if (content && *content && (*content)->m_tag == "ContentsLine" && event && *event)
            content = (*content)->get_item((*event)->m_line_index);
        if ((stack_epoch&1) && nowrunning && *nowrunning) {
            auto row=StackTraceView::capture_active(*nowrunning,content,event);
            post_stack_ui(parent,generation,stack_epoch,
                [row=std::move(row)](StackTraceView& stack) mutable {stack.apply_active(std::move(row));});
        }
        ::cw::lib::String status_text;
        if (content && *content && (!previous_content || *previous_content!=*content)) {
            // Py はツリーに保存されたラベルではなく get_status(current_event)
            // を取得する。 ゲームの所有スレッドで計算し、不変な文字列だけを公開する。Presentation
            // のコールバックから実行中のコンテントやゲーム状態を評価しない。
            const auto operation=::cw::content::get_content(*content);
            if (!operation) throw std::logic_error("active content has no status provider");
            status_text=operation->get_status(status_event);
        }
        post_debugger_ui(parent,
            [event, content, status_text=std::move(status_text), expected, generation, stack_epoch](Debugger& owner) {
                const auto view = owner.m_view_tree;
                if (!view || view.get()!=expected || owner.m_stack_epoch!=generation || generation->load()!=stack_epoch || !owner.m_visible)
                    return;
                const bool processing = view->m_processing;
                view->m_processing = true;
                if (event && *event && content && *content &&
                    view->m_items.find(*content) != view->m_items.end()) {
                    if (view->m_current_content && *view->m_current_content==*content) {
                        view->m_processing=processing;
                        return;
                    }
                    {
                        view->m_current_content = *content;
                        view->m_activeitem = view->m_items[*content];
                        view->show_item(*view->m_activeitem);
                        view->m_status_text = status_text;
                    }
                } else {
                    view->m_current_content.reset();
                    view->m_status_text.clear();
                }
                view->m_paint_pending = true;

                view->m_processing = processing;
                redraw_debugger_presentation(owner);
            });
    };
    bool on_worker=false;
    {
        std::scoped_lock lock(::cw::g_cwpy->m_game_exec_mutex);
        on_worker=::cw::g_cwpy->m_game_thread_id==std::this_thread::get_id();
    }
    if (on_worker) collect();
    else ::cw::g_cwpy->exec_func([collect](const auto&,const auto&) {
        collect();return ::cw::lib::Value{};
    });
}

// Py はスナップショット取得の予約前に processing を立てる。ネイティブ版では
// UI への反映中だけ立て、 所有者の世代に対する要求が保留または取り消された際に、処理
// 中のままにならないようにする。ワーカーは Event のデータをコピーするだけとする。
void EventView::refresh_tree()
{
    if (!m_initialized || !::cw::g_cwpy) return;
    const auto debugger=m_parent.lock();
    if (!debugger) return;
    const auto parent=debugger->m_parent;
    const auto generation=debugger->m_stack_epoch;
    const auto epoch=generation->load();
    // Python と同様、ツリーとキーの浅いコピーはゲームの所有スレッドで取得する。
    ::cw::g_cwpy->exec_func([parent,generation,epoch,expected=this](const auto&,const auto&) {
        if (!::cw::g_cwpy) return ::cw::lib::Value{};
        std::optional<std::shared_ptr<::cw::event::Event>> nowrunning;
        if ((::cw::g_cwpy->is_playingscenario() || debug_skin_enabled()) && ::cw::g_cwpy->m_areaid>=0 && ::cw::g_cwpy->m_event)
            nowrunning=::cw::g_cwpy->m_event->get_nowrunningevent();
        std::optional<std::map<::cw::lib::String,std::shared_ptr<::cw::data::CWPyElement>>> trees;
        std::optional<std::vector<::cw::lib::String>> treekeys;
        if (nowrunning && *nowrunning) {trees=(*nowrunning)->m_trees;treekeys=(*nowrunning)->m_treekeys;}
        post_debugger_ui(parent,[generation,epoch,expected,nowrunning,trees=std::move(trees),treekeys=std::move(treekeys)](Debugger& owner) mutable {
            const auto view=owner.m_view_tree;
            if (!view || view.get()!=expected || owner.m_stack_epoch!=generation || generation->load()!=epoch || !owner.m_visible) return;
            const bool processing=view->m_processing;view->m_processing=true;
            view->_refresh_tree(nowrunning,std::move(trees),std::move(treekeys));
            view->m_processing=processing;
        });
        return ::cw::lib::Value{};
    });
}

// refresh_tree と同様、ネイティブ版では有効な UI への反映中だ
// け processing を立てる。 Py は予約直後に変数を更新するが、ネ
// イティブ版では選択ツリーの反映後に要求し、同じ Event の変数を使う。
void EventView::set_event(std::optional<std::shared_ptr<::cw::event::Event>> arg_event, std::optional<std::shared_ptr<::cw::data::CWPyElement>> arg_selection)
{
    if (!m_initialized)
        return;
    if (!::cw::g_cwpy) return;
    const auto debugger=m_parent.lock();
    if (!debugger) return;
    const auto parent=debugger->m_parent;
    const auto generation=debugger->m_stack_epoch;
    const auto epoch=generation->load();
    ::cw::g_cwpy->exec_func([parent,generation,epoch,expected=this,arg_event,arg_selection](const auto&,const auto&) {
    std::optional<std::map<::cw::lib::String, std::shared_ptr<::cw::data::CWPyElement>>> trees;
    std::optional<std::vector<::cw::lib::String>> treekeys;
    if (arg_event && *arg_event) {
        trees = (*arg_event)->m_trees;
        treekeys = (*arg_event)->m_treekeys;
    }
    post_debugger_ui(parent,
        [expected,generation,epoch,arg_event, arg_selection, trees = std::move(trees),
         treekeys = std::move(treekeys)](Debugger& owner) mutable {
            const auto view = owner.m_view_tree;
            if (!view || view.get()!=expected || owner.m_stack_epoch!=generation || generation->load()!=epoch || !owner.m_visible)
                return;
            const bool processing = view->m_processing;
            view->m_processing = true;
            view->_refresh_tree(arg_event, std::move(trees), std::move(treekeys));
            if (arg_selection && *arg_selection) {
                const auto found = view->m_items.find(*arg_selection);
                if (found != view->m_items.end()) {
                    view->set_selectionitem(found->second);
                    view->show_item(found->second);
                }
            }
            view->m_processing = processing;
            if (owner.m_view_var)
                owner.m_view_var->refresh_variablelist(arg_event);
            redraw_debugger_presentation(owner);
        });
    return ::cw::lib::Value{};
    });
}

void EventView::_refresh_tree(std::optional<std::shared_ptr<::cw::event::Event>> arg_nowrunning, std::optional<std::map<::cw::lib::String, std::shared_ptr<::cw::data::CWPyElement>>> arg_trees, std::optional<std::vector<::cw::lib::String>> arg_treekeys)
{
    // 実行中の Event がなければ保持中の行とコンテントへのポインターは無効なので、表示を消し、Event なしで変数を更新する。
    if (!arg_nowrunning || !*arg_nowrunning) {
        event_scroll_cancel();
        m__linenumwidth = 20;
        m_leftbarwidth = ::cw::dialog::is_all_mode() ? 24 : 44;
        m_items.clear();
        m_itemstates.clear();
        m_itemlist.clear();
        m_activeitem.reset();
        set_selectionitem(std::nullopt);
        m_selectionindex = -1;
        m_current_event.reset();
        m_current_tree.reset();
        m_current_content.reset();
        m_maxwidth = 1;
        m_maxheight = 1;
        m_virtual_width = 1;
        m_virtual_height = 1;
        m_view_start_x = 0;
        m_view_start_y = 0;
        m_status_text.clear();
        m_refresh_pending = true;
        if (const auto parent = m_parent.lock(); parent && parent->m_view_var)
            parent->m_view_var->refresh_variablelist(std::nullopt);
        return;
    }
    if (!arg_trees || !arg_treekeys)
        return;
    // EventView の項目は Event とコンテントの同一性を保持するため、ツリーのマップが等しくても Event が変われば再構築する。
    const bool changed = !m_current_event || !*m_current_event || *m_current_event != *arg_nowrunning ||
                         !m_current_tree || *m_current_tree != *arg_trees;
    m_current_event = *arg_nowrunning;
    if (!changed)
        return;
    event_scroll_cancel();
    m_current_tree = *arg_trees;
    m_activeitem.reset();
    set_selectionitem(std::nullopt);
    m_selectionindex = -1;
    m_items.clear();
    m_itemstates.clear();
    m_itemlist.clear();
    m_maxwidth = 0;
    m_maxheight = 0;
    const auto font = debugger_logical_metrics().font;
    const auto active_label = ::cw::lib::ui::render_label(" // ACTIVE!", font.pixels,
        font.bold, {0, 0, 0}, font.face);
    const auto start_icon = get_contenticon(::cw::data::make_element("Start"));
    const ::cw::lib::Integer shiftx = start_icon && *start_icon ? (*start_icon)->size.width : 16;
    m_lineheight = (std::max<Integer>)(start_icon && *start_icon ? (*start_icon)->size.height + 2 : 18,
        active_label ? active_label->size.height : font.pixels);
    for (const auto& name : *arg_treekeys) {
        const auto tree = arg_trees->find(name);
        if (tree != arg_trees->end() && tree->second)
            create_item(std::nullopt, tree->second, shiftx, {});
    }
    if (!m_itemlist.empty()) {
        const auto state = m_itemstates.find(m_itemlist.back());
        if (state != m_itemstates.end())
            m_maxheight = state->second.y + state->second.height;
    }
    const auto line_count = std::max<std::size_t>(1, m_itemlist.size());
    Integer digit_width = 0;
    for (char digit = '0'; digit <= '9'; ++digit)
        digit_width = (std::max)(digit_width, ::cw::lib::ui::label_width(
            ::cw::lib::String(1, digit), font.pixels, font.bold, font.face));
    m_leftbarwidth = (::cw::dialog::is_all_mode() ? 4 : 24) + (std::max<Integer>)(20,
        static_cast<Integer>(std::to_string(line_count).size()) * digit_width + 5);
    m_virtual_width = (std::max<Integer>)(1, m_maxwidth + (active_label ? active_label->size.width : 0));
    m_virtual_height = std::max<::cw::lib::Integer>(1, m_maxheight);
    m_scrollrate_x = shiftx;
    m_scrollrate_y = m_lineheight;
    m_view_start_x = 0;
    m_view_start_y = 0;
    m_refresh_pending = true;
    m_paint_pending = true;
    m_status_text.clear();
    if (const auto parent = m_parent.lock())
        redraw_debugger_presentation(*parent);
    if (const auto parent = m_parent.lock(); parent && parent->m_view_var)
        parent->m_view_var->refresh_variablelist(*arg_nowrunning);
}

void EventView::create_item(std::optional<std::shared_ptr<::cw::debug::debugger::EventViewItem>> arg_parentitem, std::shared_ptr<::cw::data::CWPyElement> arg_contents, ::cw::lib::Integer arg_shiftx, std::shared_ptr<::cw::lib::DeviceContext> arg_dc)
{
    (void)arg_dc;
    if (!arg_contents || !m_current_event || !*m_current_event)
        return;
    const bool isline = arg_contents->m_tag == "ContentsLine";
    std::vector<std::shared_ptr<::cw::data::CWPyElement>> contents;
    if (isline)
        contents = arg_contents->m_children;
    else
        contents.push_back(arg_contents);
    std::optional<std::shared_ptr<::cw::debug::debugger::EventViewItem>> parentitem = arg_parentitem;
    for (std::size_t index = 0; index < contents.size(); ++index) {
        const auto content = contents[index];
        if (!content)
            continue;
        std::optional<std::shared_ptr<::cw::data::CWPyElement>> parent;
        ::cw::lib::Integer x = 0;
        if (parentitem && *parentitem) {
            const auto parentstate = m_itemstates.find(*parentitem);
            if (parentstate != m_itemstates.end()) {
                parent = parentstate->second.content;
                x = parentstate->second.x;
                if (parentstate->second.branch)
                    x += arg_shiftx;
            }
        }
        ::cw::lib::Integer y = 0;
        if (!m_itemlist.empty()) {
            const auto previous = m_itemstates.find(m_itemlist.back());
            if (previous != m_itemstates.end())
                y = previous->second.y + previous->second.height;
        }
        std::vector<std::shared_ptr<::cw::data::CWPyElement>> nextdata;
        if (isline && index + 1 < contents.size()) {
            nextdata.push_back(contents[index + 1]);
        } else {
            for (const auto& child : content->m_children) {
                if (child && child->m_tag == "Contents") {
                    nextdata = child->m_children;
                    break;
                }
            }
        }
        auto item = std::make_shared<::cw::debug::debugger::EventViewItem>();
        ItemState state;
        state.parent = parent;
        state.content = content;
        state.nextdata = nextdata;
        state.cwxpath = content->get_cwxpath();
        state.text = parent ? content->get("name", "") : content->get("name", "");
        state.x = x;
        state.y = y;
        state.height = nextdata.empty() ? m_lineheight * 2 : m_lineheight;
        state.width = 0; // 下で実際の Unicode フォントとアイコンの計測値から設定する。
        state.branch = nextdata.size() >= 2 || content->m_tag == "Branch" || !parent;
        item->m_content = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(content));
        item->m_cwxpath = state.cwxpath;
        item->m_height = state.height;
        item->m_nextlen = static_cast<::cw::lib::Integer>(nextdata.size());
        item->m_parent = parent ? ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(*parent)) : ::cw::lib::Value{};
        item->m_text = state.text;
        item->m_width = state.width;
        item->initialize(parent, *m_current_event, content, nextdata, {x, y}, m_lineheight, arg_dc);
        state.text = item->m_text_typed;
        state.width = std::max(state.width, item->m_width_typed);
        item->m_text = state.text;
        item->m_width = state.width;
        m_itemstates[item] = state;
        m_items[content] = item;
        m_itemlist.push_back(item);
        m_maxwidth = std::max(m_maxwidth, state.x + state.width);
        if (!(isline && index + 1 < contents.size())) {
            for (const auto& child : nextdata)
                create_item(item, child, arg_shiftx, {});
        }
        parentitem = item;
    }
}

void EventViewItem::initialize(std::optional<std::shared_ptr<::cw::data::CWPyElement>> arg_parent, std::shared_ptr<::cw::event::Event> arg_event, std::shared_ptr<::cw::data::CWPyElement> arg_content, std::vector<std::shared_ptr<::cw::data::CWPyElement>> arg_nextdata, std::tuple<::cw::lib::Integer, ::cw::lib::Integer> arg_pos, ::cw::lib::Integer arg_lineheight, std::shared_ptr<::cw::lib::DeviceContext> arg_dc)
{
    (void)arg_dc;
    m_parent_element = arg_parent;
    m_content_element = std::move(arg_content);
    m_nextdata_elements = std::move(arg_nextdata);
    m_pos_typed = arg_pos;
    m_cwxpath_typed.clear();
    m_text_typed.clear();
    m_width_typed = 0;
    m_branch = false;
    m_initialized = false;
    if (!m_content_element)
        return;
    m_cwxpath_typed = m_content_element->get_cwxpath();
    if (arg_parent && *arg_parent && arg_event) {
        try {
            const auto parent_content = ::cw::content::get_content(*arg_parent);
            if (parent_content)
                m_text_typed = parent_content->get_childname(m_content_element, arg_event);
        } catch (...) {
            // 独自または未知のコンテント型では、代替表示に XML の名前を使う。
            m_text_typed = m_content_element->get("name", "");
        }
    }
    // Python と同様、名前のない子コンテントはアイコンのみの行にする。
    if (!arg_parent || !*arg_parent)
        m_text_typed = m_content_element->get("name", "");
    m_image = {};
    if (const auto icon = get_contenticon(m_content_element)) {
        m_image = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(*icon));
        m_width_typed = (*icon)->size.width;
    }
    m_nextlen = static_cast<::cw::lib::Integer>(m_nextdata_elements.size());
    m_height = m_nextlen ? arg_lineheight : arg_lineheight * 2;
    if (!m_text_typed.empty()) {
        const auto font = debugger_logical_metrics().font;
        m_width_typed += 2 + ::cw::lib::ui::label_width(m_text_typed, font.pixels, font.bold, font.face);
    }
    m_branch = m_nextlen >= 2 || m_content_element->m_tag == "Branch" || !arg_parent.has_value();
    m_cwxpath = m_cwxpath_typed;
    m_text = m_text_typed;
    m_width = m_width_typed;
    if (arg_parent && *arg_parent)
        m_parent = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(*arg_parent));
    else
        m_parent = {};
    m_content = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(m_content_element));
    m_initialized = true;
}

bool EventViewItem::is_branch()
{
    if (m_initialized)
        return m_branch;
    return m_nextlen >= 2;
}

bool EventViewItem::is_contains(std::tuple<::cw::lib::Integer, ::cw::lib::Integer> arg_pos)
{
    const auto y = std::get<1>(arg_pos);
    const auto top = std::get<1>(m_pos_typed);
    return top <= y && y < top + m_height;
}

StackTraceView::StackTraceView()
{
    initialize({});
}

void StackTraceView::initialize(std::shared_ptr<::cw::debug::debugger::Debugger> arg_parent)
{
    m_parent = std::move(arg_parent);
    m_stack_snapshot = {};
    m_row_sources.clear();
    m__has_curcontent = false;
    // wx.ImageList.Add の順序をデータ側でも固定し、SDL/native UI が同じ
    // インデックスを利用できるようにする。実ビットマップの生成はUI層へ委譲。
    m_imgidx_area = 0;
    m_imgidx_battle = 1;
    m_imgidx_package = 2;
    m_imgidx_card = 3;
    m_imgidx_event = 4;
    m_imgidx_link_start = 5;
    m_imgidx_call_start = 6;
    m_imgidx_link_package = 7;
    m_imgidx_call_package = 8;
    m_imgidx_effect = 9;
    m_imgidx_skill = 10;
    m_imgidx_item = 11;
    m_imgidx_beast = 12;
    m_imgidx_contents.clear();
    m_icons.clear();
    m_list_view.cancel();
    m_list_view.horizontal.position=0;
    m_imglist = {};
    m_list.clear();
    m_rows.clear();
    m_row_images.clear();
    m_selected_row = -1;
    m_last_error.clear();
    m_refresh_pending = false;
    m_initialized = true;
    _bind();
}


::cw::dialog::DialogPresentation StackTraceView::stack_presentation(
    ::cw::lib::Size size,bool focused,Integer& first_row)
{
    // Python の StackTraceView は、見出しがなく、アイコンを持ち、幅を自動調整するレポート一覧である。
    if(m_selected_row>=static_cast<Integer>(m_rows.size()) || m_selected_row<-1) m_selected_row=-1;
    auto result=m_list_view.render(size,{},m_column_widths,static_cast<Integer>(m_rows.size()),
        m_selected_row,focused,first_row,
        [this](Integer row,Integer){return m_rows[static_cast<std::size_t>(row)];},
        [this](Integer row)->std::shared_ptr<::cw::lib::Surface> {
            if(row>=static_cast<Integer>(m_row_images.size())) return {};
            const auto index=m_row_images[static_cast<std::size_t>(row)];
            if(const auto found=m_icons.find(index);found!=m_icons.end()) return found->second;
            const std::array<const char*,13> names{"AREA","BATTLE","PACK","CARD","EVENT",
                "EVT_LINK_START","EVT_CALL_START","EVT_LINK_PACKAGE","EVT_CALL_PACKAGE",
                "EVT_EFFECT","EVT_GET_SKILL","EVT_GET_ITEM","EVT_GET_BEAST"};
            ::cw::lib::String name;
            if(index>=0 && index<static_cast<Integer>(names.size())) name=names[static_cast<std::size_t>(index)];
            else for(const auto& [key,value]:m_imgidx_contents) if(value==index) {name=key;break;}
            if(name.empty()) return {};
            auto bitmap=::cw::util::load_wxbmp("Data/Debugger/"+name+".png",
                true,{},{},std::nullopt,true,false,false,::cw::lib::Value(1));
            if(!bitmap || bitmap->size.width<=1 || bitmap->size.height<=1) return {};
            m_icons[index]=bitmap;
            return bitmap;
        },true);
    result.route="DebuggerStackTrace";
    m_refresh_pending=false;
    return result;
}

void StackTraceView::_bind()
{
    // wx.EVT_LEFT_DCLICK はUIブリッジがOnDClickへ配送する。
    m_bound = true;
}

void StackTraceView::OnDClick(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_event)
        return;
    if (!::cw::g_cwpy->m_event->is_paused() && !::cw::g_cwpy->is_showingmessage())
        return;
    if (arg_event && arg_event->id >= 0)
        m_selected_row = arg_event->id;
    if (m_selected_row < 0 || static_cast<std::size_t>(m_selected_row) >= m_list.size())
        return;
    const auto parent = m_parent.lock();
    if (!parent || !parent->m_view_tree)
        return;
    const auto& [event, content] = m_list[static_cast<std::size_t>(m_selected_row)];
    if (event)
        parent->m_view_tree->set_event(event, content);
}

bool StackTraceView::enable_eventview()
{
    return ::cw::g_cwpy && (::cw::g_cwpy->is_playingscenario() || debug_skin_enabled());
}

void StackTraceView::refresh_stackinfo()
{
    // Python と同様にワーカーへスナップショットを要求し、UI から EventInterface を直接調べない。
    if (const auto parent=m_parent.lock()) parent->refresh_stackinfo();
}

StackTraceSnapshot StackTraceView::capture_snapshot()
{
    StackTraceSnapshot result;
    StackTraceView builder;
    if (!builder.enable_eventview() || !::cw::g_cwpy->m_event) return result;
    auto& events=*::cw::g_cwpy->m_event;
    const auto limit=std::clamp(events.m_stackinfo_len,::cw::lib::Integer{0},
        static_cast<::cw::lib::Integer>(events.m_stackinfo.size()));
    for (::cw::lib::Integer i=0;i<limit;++i) {
        const auto& item=events.m_stackinfo[static_cast<std::size_t>(i)];
        result.frames.push_back(item ? capture_item(*item) : std::nullopt);
    }
    const auto current=events.get_event();
    const auto nowrunning=events.get_nowrunningevent();
    std::optional<std::shared_ptr<::cw::data::CWPyElement>> content;
    if (current && *current) {
        content=(*current)->m_cur_content;
        if (content && *content && (*content)->m_tag=="ContentsLine") {
            const auto index=(*current)->m_line_index;
            if (index>=0 && static_cast<std::size_t>(index)<(*content)->m_children.size())
                content=(*content)->m_children[static_cast<std::size_t>(index)];
            else content.reset();
        }
    }
    if (nowrunning && *nowrunning) result.active=capture_active(*nowrunning,content,current);
    return result;
}

std::optional<StackTraceRow> StackTraceView::capture_item(::cw::lib::Value item)
{
    StackTraceView builder;
    const auto [name,icon,data]=builder._get_item(std::move(item));
    if (!name || !icon || !data) return {};
    return StackTraceRow{*data,*name,{},*icon,{}};
}

std::optional<StackTraceRow> StackTraceView::capture_active(
    std::shared_ptr<::cw::event::Event> event,
    std::optional<std::shared_ptr<::cw::data::CWPyElement>> content,
    std::optional<std::shared_ptr<::cw::event::Event>> status_event)
{
    if (!event || !content || !*content) return {};
    StackTraceView builder;
    const auto [name,icon]=builder._get_info(*content,status_event ? status_event : event);
    StackTraceRow row{{std::move(event),*content},name,{},icon,{}};
    for (const auto& [key,index]:builder.m_imgidx_contents)
        if (index==icon) {row.icon_name=key;break;}
    const auto bitmap=builder.m_icons.find(icon);
    if (bitmap!=builder.m_icons.end()) row.bitmap=bitmap->second;
    return row;
}

void StackTraceView::apply_snapshot(StackTraceSnapshot snapshot)
{
    m_stack_snapshot=std::move(snapshot);
    m_selected_row=-1; // Python の DeleteAllItems と同様、全体更新時には選択を解除する。
    rebuild_rows();
}

void StackTraceView::rebuild_rows()
{
    std::optional<::cw::lib::Integer> selected_source;
    if (m_selected_row>=0 && static_cast<std::size_t>(m_selected_row)<m_row_sources.size())
        selected_source=m_row_sources[static_cast<std::size_t>(m_selected_row)];
    m_list.clear();m_rows.clear();m_row_images.clear();m_row_sources.clear();m_selected_row=-1;
    const auto append=[&](const StackTraceRow& row,::cw::lib::Integer source) {
        auto icon=row.icon;
        if (!row.icon_name.empty()) {
            const auto next=static_cast<::cw::lib::Integer>(13+m_imgidx_contents.size());
            icon=m_imgidx_contents.try_emplace(row.icon_name,next).first->second;
            if (row.bitmap) m_icons[icon]=row.bitmap;
        }
        if (selected_source && *selected_source==source) m_selected_row=static_cast<::cw::lib::Integer>(m_list.size());
        m_row_sources.push_back(source);
        m_list.push_back(row.entry);m_rows.push_back(row.text);m_row_images.push_back(icon);
    };
    for (std::size_t i=0;i<m_stack_snapshot.frames.size();++i)
        if (const auto& row=m_stack_snapshot.frames[i]) append(*row,static_cast<::cw::lib::Integer>(i));
    m__has_curcontent=m_stack_snapshot.active.has_value();
    if (m_stack_snapshot.active) append(*m_stack_snapshot.active,-1);
    m_last_error.clear();m_refresh_pending=true;
}

void StackTraceView::append_row(std::optional<StackTraceRow> row)
{
    m_stack_snapshot.frames.push_back(std::move(row));
    rebuild_rows();
}

void StackTraceView::replace_row(::cw::lib::Integer index,std::optional<StackTraceRow> row)
{
    if (index<0 || static_cast<std::size_t>(index)>=m_stack_snapshot.frames.size()) {
        m_last_error="stack trace row out of range";return;
    }
    m_stack_snapshot.frames[static_cast<std::size_t>(index)]=std::move(row);
    rebuild_rows();
}

void StackTraceView::apply_active(std::optional<StackTraceRow> row)
{
    m_stack_snapshot.active=std::move(row);
    rebuild_rows();
}

std::tuple<std::optional<::cw::lib::String>, std::optional<::cw::lib::Integer>, std::optional<std::tuple<std::shared_ptr<::cw::event::Event>, std::optional<std::shared_ptr<::cw::data::CWPyElement>>>>> StackTraceView::_get_item(::cw::lib::Value arg_evt)
{
    const auto event = object_value<::cw::event::Event>(arg_evt);
    if (event) {
        auto start = event->m_starttree;
        if (!start || !*start)
            return {};
        auto ancestor = *start;
        std::optional<::cw::lib::Integer> icon;
        while (ancestor && ancestor->m_cwxparent && *ancestor->m_cwxparent) {
            ancestor = *ancestor->m_cwxparent;
            if (ancestor->m_tag == "Area") icon = m_imgidx_area;
            else if (ancestor->m_tag == "Battle") icon = m_imgidx_battle;
            else if (ancestor->m_tag == "Package") icon = m_imgidx_package;
            else if (ancestor->m_tag == "SkillCard") icon = m_imgidx_skill;
            else if (ancestor->m_tag == "ItemCard") icon = m_imgidx_item;
            else if (ancestor->m_tag == "BeastCard") icon = m_imgidx_beast;
            else if (ancestor->m_tag == "MenuCard" || ancestor->m_tag == "LargeMenuCard" || ancestor->m_tag == "EnemyCard") icon = m_imgidx_card;
            else continue;
            break;
        }
        if (!icon || !ancestor)
            return {};
        ::cw::lib::String name;
        if (ancestor->m_tag == "EnemyCard") {
            const auto resid = ancestor->getint("Property/Id", std::nullopt, 0);
            const auto data = system_data();
            const auto enemy = data ? data->get_castname(resid) : std::optional<::cw::lib::String>{};
            name = !enemy ? "(未設定)" : (enemy->empty() ? "(名称なし)" : *enemy);
        } else {
            name = ancestor->gettext("Property/Name", "(名称なし)");
        }
        const auto key = event->m_treekeys.empty() || event->m_treekeys.front().empty() ? "イベント名なし" : event->m_treekeys.front();
        name += " (" + key + ")";
        auto content = event->m_starttree;
        if (content && *content && (*content)->m_tag == "ContentsLine") {
            if ((*content)->m_children.empty())
                content.reset();
            else
                content = (*content)->m_children.front();
        }
        if (!content || !*content)
            return {};
        return {name, icon, std::tuple<std::shared_ptr<::cw::event::Event>, std::optional<std::shared_ptr<::cw::data::CWPyElement>>>{event, *content}};
    }

    const auto frame = object_value<StackTraceFrame>(arg_evt);
    if (!frame || !frame->event)
        return {};
    auto content = frame->content;
    if (content && *content && (*content)->m_tag == "ContentsLine") {
        const auto index = frame->line_index;
        if (index < 0 || static_cast<std::size_t>(index) >= (*content)->m_children.size())
            return {};
        content = (*content)->m_children[static_cast<std::size_t>(index)];
    }
    if (!content || !*content)
        return {};
    const auto type_it = (*content)->m_attributes.find("type");
    const auto type = type_it == (*content)->m_attributes.end() ? ::cw::lib::String{} : type_it->second;
    std::optional<::cw::lib::Integer> icon;
    if ((*content)->m_tag == "Call" && type == "Start") icon = m_imgidx_call_start;
    else if ((*content)->m_tag == "Link" && type == "Start") icon = m_imgidx_link_start;
    else if ((*content)->m_tag == "Call" && type == "Package") icon = m_imgidx_call_package;
    else if ((*content)->m_tag == "Link" && type == "Package") icon = m_imgidx_link_package;
    else if ((*content)->m_tag == "Effect" && type.empty()) icon = m_imgidx_effect;
    else {
        m_last_error = "unknown stack content: " + (*content)->m_tag + type;
        return {};
    }
    const auto [name, info_icon] = _get_info(*content, frame->event);
    (void)info_icon;
    return {name, icon, std::tuple<std::shared_ptr<::cw::event::Event>, std::optional<std::shared_ptr<::cw::data::CWPyElement>>>{frame->event, *content}};
}

std::tuple<::cw::lib::String, ::cw::lib::Integer> StackTraceView::_get_info(
    std::shared_ptr<::cw::data::CWPyElement> arg_cur_content,
    std::optional<std::shared_ptr<::cw::event::Event>> arg_event)
{
    if (!arg_cur_content)
        return {"", m_imgidx_event};
    ::cw::lib::String name;
    if (const auto content = ::cw::content::get_content(arg_cur_content))
        name = content->get_status(std::move(arg_event));
    // Py はタグの文字列と type をそのまま使ってキャッシュする。type の欠落と空文字列は同じ枠を
    // 使う。 これは get_contenticon が使う大文字化済みのリソース検索キーとは独立している。
    const auto image_name = arg_cur_content->m_tag + arg_cur_content->get("type", "");
    if (const auto cached = m_imgidx_contents.find(image_name); cached != m_imgidx_contents.end())
        return {name, cached->second};
    // ネイティブ版のリソース境界では、ビットマップがない場合に ImageList
    // へ null を追加せず、既存の汎用 EVENT アイコンを代わりに使う。
    const auto content_icon = get_contenticon(arg_cur_content);
    if (!content_icon)
        return {name, m_imgidx_event};
    const auto next = static_cast<::cw::lib::Integer>(13 + m_imgidx_contents.size());
    const auto it = m_imgidx_contents.emplace(image_name, next).first;
    m_icons[it->second]=*content_icon;
    return {name, it->second};
}

// StackTraceView 互換 API の直接呼び出しは公開済みスナップショットを変更する。Debugger のラッパーは、ワーカーの最新状態を解決してからこの表示へ変更を送る。
void StackTraceView::append_stackinfo_cwpy(::cw::lib::Value arg_item)
{
    append_row(capture_item(std::move(arg_item)));
}

void StackTraceView::pop_stackinfo_cwpy()
{
    if (m_stack_snapshot.frames.empty()) return; // 現在のコンテントを示す末尾の要素は削除しない。
    m_stack_snapshot.frames.pop_back();
    rebuild_rows();
}

void StackTraceView::replace_stackinfo_cwpy(::cw::lib::Integer arg_index, ::cw::lib::Value arg_item)
{
    // 互換用の入口は、ワーカーの現在の長さではなく、この公開済みモデルに対して操作する。
    replace_row(static_cast<::cw::lib::Integer>(m_stack_snapshot.frames.size())+arg_index,
        capture_item(std::move(arg_item)));
}

void StackTraceView::clear_stackinfo_cwpy()
{
    apply_snapshot({});
}

void StackTraceView::refresh_activeitem(std::shared_ptr<::cw::event::Event> arg_nowrunning,
    std::optional<std::shared_ptr<::cw::data::CWPyElement>> arg_cur_content)
{
    if (arg_nowrunning && arg_cur_content && *arg_cur_content)
        apply_active(capture_active(std::move(arg_nowrunning),std::move(arg_cur_content)));
}

VariableListCtrl::VariableListCtrl()
{
    initialize({});
}

void VariableListCtrl::initialize(std::shared_ptr<::cw::debug::debugger::Debugger> arg_parent)
{
    m_refresh_epoch.fetch_add(1);
    m_refresh_frame = arg_parent ? arg_parent->m_parent : std::weak_ptr<::cw::frame::Frame>{};
    m_parent = std::move(arg_parent);
    m_list.clear();
    m_imgidx_flag = 0;
    m_imgidx_step = 1;
    m_imgidx_variant = 2;
    m_imgidx_flag_l = 3;
    m_imgidx_step_l = 4;
    m_imgidx_variant_l = 5;
    m_mi_initvars = g_ID_INIT_VARIABLES;
    m_selected_row = -1;
    m_last_refreshed_row = -1;
    m_item_count = 0;
    m_icons = {};
    m_icons_loaded = false;
    m_visible_rows = 1;
    m_list_view.cancel();
    m_list_view.horizontal.position=0;
    m_edit_choices.clear();
    m_last_different_scenario = false;
    m_last_error.clear();
    m_operation_log.clear();
    m_initialized = true;
    refresh_variablelist_impl(std::nullopt);
    _bind();
}

::cw::dialog::DialogPresentation VariableListCtrl::variable_presentation(
    ::cw::lib::Size size, bool focused, Integer& first_row)
{
    // UIの実装は一つに統一し、
    // 別経路の実装を設けない。
    if(m_selected_row>=static_cast<Integer>(m_list.size()) || m_selected_row<-1) m_selected_row=-1;
    if (!m_icons_loaded) {
        const std::array<const char*,6> names{"FLAG","STEP","VARIANT","LOCAL_FLAG","LOCAL_STEP","LOCAL_VARIANT"};
        for (std::size_t i = 0; i < names.size(); ++i) {
            auto bitmap = ::cw::util::load_wxbmp(::cw::lib::String("Data/Debugger/") + names[i] + ".png",
                true, {}, {}, std::nullopt, true, false, false, ::cw::lib::Value(1));
            if (bitmap && bitmap->size.width > 1 && bitmap->size.height > 1) m_icons[i] = std::move(bitmap);
        }
        m_icons_loaded = true;
    }
    auto result=m_list_view.render(size,m_columns,m_column_widths,static_cast<Integer>(m_list.size()),
        m_selected_row,focused,first_row,
        [this](Integer row,Integer col){return OnGetItemText(row,col);},
        [this](Integer row)->std::shared_ptr<::cw::lib::Surface>{
            const auto index=OnGetItemImage(row);
            return index>=0 && index<static_cast<Integer>(m_icons.size())?m_icons[static_cast<std::size_t>(index)]:nullptr;
        });
    result.route="DebuggerVariables";
    m_visible_rows=m_list_view.visible_rows;
    m_refresh_pending=false;
    return result;
}
bool VariableListCtrl::autosize_column(int index)
{
    return m_list_view.autosize(index,m_column_widths,m_columns,static_cast<Integer>(m_list.size()),
        [this](Integer row,Integer col){return OnGetItemText(row,col);});
}

bool VariableListCtrl::navigate(::cw::dialog::DialogPresentationKey key, Integer& first_row)
{
    m_list_view.row_count=static_cast<Integer>(m_list.size());
    m_list_view.visible_rows=m_visible_rows;
    const bool handled=m_list_view.navigate(key,m_selected_row,first_row);
    if(handled) m_refresh_pending=true;
    return handled;
}

void VariableListCtrl::_bind()
{
    // wx.EVT_LEFT_DCLICK, EVT_MENU(ID_INIT_VARIABLES), EVT_CONTEXT_MENU に相当する
    // イベント契約だけを保持し、実ウィジェットへの接続はUI層へ委譲する。
    m_bound = true;
}

void VariableListCtrl::OnContextMenu(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if (const auto parent = m_parent.lock())
        parent->open_variable_menu(parent->m_variable_rect.x + 12,
                                   parent->m_variable_rect.y + 22);
}

void VariableListCtrl::OnInitVariables(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    init_variables();
}

void VariableListCtrl::init_variables()
{
    queue_reset();
}

bool VariableListCtrl::queue_reset(std::function<void(::cw::lib::Callback)> enqueue,
                                  std::function<void(bool)> after_reset)
{
    // 選択スコープは Frame に属する。ここでは識別情報と権限を保持
    // し、 現在値・既定値の読み取りと保存はゲームワーカーだけで行う。
    Snapshot entries;
    for (const auto& entry : m_list)
        if (entry.editable) entries.push_back(entry);
    if (!enqueue) {
        if (!::cw::g_cwpy) return false;
        enqueue = [](::cw::lib::Callback job) {
            if (::cw::g_cwpy) ::cw::g_cwpy->exec_func(std::move(job));
        };
    }
    if (!after_reset) after_reset = [](bool changed) {
        if (!::cw::g_cwpy) return;
        ::cw::g_cwpy->play_sound("signal", false, 100, 1, 0, 0, false);
        if (changed) {
            VariableListCtrl::_update_variablesowner();
            if (::cw::g_cwpy->m_event) ::cw::g_cwpy->m_event->refresh_variablelist();
        }
    };
    const auto expected = weak_from_this();
    const auto frame = m_refresh_frame;
    const auto epoch = m_refresh_epoch.load();
    const auto once = std::make_shared<std::atomic_bool>(false);
    const auto publish = [expected, frame, epoch](Snapshot rows, ::cw::lib::String error) {
        post_debugger_ui(frame, [expected, epoch, rows = std::move(rows), error = std::move(error)]
            (Debugger& debugger) {
            const auto view = expected.lock();
            if (!view || debugger.m_view_var != view || !debugger.m_visible ||
                view->m_refresh_epoch.load() != epoch) return;
            if (!error.empty() || debugger.m_last_error == view->m_last_error)
                debugger.m_last_error = error;
            view->m_last_error = error;
            for (const auto& row : rows)
                for (auto& current : view->m_list)
                    if (current.variable == row.variable) {
                        const bool different = current.display && current.display->different_scenario;
                        current.display = row.display;
                        if (current.display) current.display->different_scenario = different;
                    }
            redraw_variable_presentation(debugger);
        });
    };
    try {
        enqueue([entries = std::move(entries), after_reset = std::move(after_reset), once, publish]
            (const auto&, const auto&) mutable {
            if (once->exchange(true)) return ::cw::lib::Value{};
            bool changed = false;
            ::cw::lib::String error;
            try {
                for (const auto& entry : entries)
                    std::visit([&](const auto& item) {
                        using T = std::remove_cvref_t<decltype(item)>;
                        if (!item) return;
                        bool differs;
                        if constexpr (std::is_same_v<T, std::shared_ptr<::cw::data::Variant>>)
                            differs = item->m_value.storage() != item->m_defaultvalue.storage();
                        else differs = item->m_value != item->m_defaultvalue;
                        if (!differs) return;
                        item->set(item->m_defaultvalue, false);
                        item->write_value();
                        changed = true;
                    }, entry.variable);
                after_reset(changed); // Python と同様、変更を伴わないリセットも成功として通知する。
            } catch (const std::exception& ex) {error = ex.what();}
            catch (...) {error = "状態変数を初期値へ戻せませんでした。";}
            Snapshot updated;
            try {
                for (auto& entry : entries) updated.push_back(snapshot_entry(std::move(entry)));
            } catch (const std::exception& ex) {if (error.empty()) error = ex.what();}
            catch (...) {if (error.empty()) error = "状態変数の表示値を取得できませんでした。";}
            publish(std::move(updated), std::move(error));
            return ::cw::lib::Value{};
        });
        return true;
    } catch (const std::exception& ex) {
        once->store(true);
        publish({}, ex.what());
    } catch (...) {
        once->store(true);
        publish({}, "状態変数の初期化を予約できませんでした。");
    }
    return false;
}

void VariableListCtrl::_update_variablesowner()
{
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_event || !::cw::g_cwpy->m_event->m_in_inusecardevent)
        return;
    const auto inusecard = ::cw::g_cwpy->m_event->get_inusecard();
    if (!inusecard || !*inusecard)
        return;
    const auto owner = (*inusecard)->get_owner();
    if (!owner)
        return;
    const auto player = object_value<::cw::character::Player>(*owner);
    if (!player)
        return;
    const auto data = object_value<::cw::data::CWPyElementTree>(player->m_data);
    if (data)
        data->m_is_edited = true;
}

void VariableListCtrl::OnDClick(std::shared_ptr<::cw::lib::Window> arg_event)
{
    {
        if (arg_event && arg_event->id >= 0 && arg_event->id < static_cast<::cw::lib::Integer>(m_list.size()))
            m_selected_row = arg_event->id;
        if (m_selected_row < 0 || static_cast<std::size_t>(m_selected_row) >= m_list.size())
            return;
        // モーダル表示中も Frame のコールバックが処理されるため、値の選択画面を開いている間
        // に一覧更新で vector が置き換わり得る。 行への参照ではなく、変数自体を保持する。
        const auto& selected_entry = m_list[static_cast<std::size_t>(m_selected_row)];
        const auto entry = selected_entry.display ? selected_entry : snapshot_entry(selected_entry);
        if (!entry.editable)
            return;
        m_edit_choices.clear();
        std::visit([&](const auto& variable) {
            using T = std::remove_cvref_t<decltype(variable)>;
            if constexpr (std::is_same_v<T, std::shared_ptr<::cw::data::Flag>>) {
                if (variable) {
                    m_edit_choices = entry.display->choices;
                    m_operation_log.push_back("open_flag_choice:" + entry.display->name);
                    const auto parent = m_parent.lock();
                    const auto selected = common_debugger_choose(
                        entry.display->name, "変更したい値を選択してください。",
                        entry.display->choices,
                        {}, false); // wx.SingleChoiceDialog は既定で先頭項目を選択する。
                    if (selected && !selected->empty()) {
                        queue_edit(entry, ::cw::lib::Value(selected->front() == 0));
                    }
                }
            } else if constexpr (std::is_same_v<T, std::shared_ptr<::cw::data::Step>>) {
                if (variable) {
                    m_edit_choices = entry.display->choices;
                    m_operation_log.push_back("open_step_choice:" + entry.display->name);
                    const auto parent = m_parent.lock();
                    const auto selected = common_debugger_choose(
                        entry.display->name, "変更したい値を選択してください。",
                        entry.display->choices,
                        {}, false);
                    if (selected && !selected->empty()) {
                        queue_edit(entry, ::cw::lib::Value(static_cast<Integer>(selected->front())));
                    }
                }
            } else if constexpr (std::is_same_v<T, std::shared_ptr<::cw::data::Variant>>) {
                _edit_variant(variable, entry.local, *entry.display);
            }
        }, entry.variable);
    }}

void VariableListCtrl::_edit_variant(std::shared_ptr<::cw::data::Variant> arg_variant, bool arg_local,
                                    VariableDisplay captured)
{
    if (!arg_variant)
        return;
    {
        const auto* display = &captured;
        const bool different_scenario = display->different_scenario;
        m_operation_log.push_back("open_variant_editor:" + display->name);
        m_last_different_scenario = different_scenario;
        const auto parent = m_parent.lock();
        auto dialog = std::make_shared<::cw::debug::edit::VariantEditDialog>();
        auto dialog_parent = std::make_shared<::cw::lib::Window>();
        dialog_parent->title = display->name;
        dialog->initialize(dialog_parent, display->name,
                           "コモンの型と値",
                           display->raw_value, different_scenario);
        if (::cw::debug::edit::show_modal(*dialog)) {
            if (dialog->m_value) {
                queue_edit({arg_variant, arg_local, true, captured}, *dialog->m_value);
            }
        }
    }}

bool VariableListCtrl::queue_edit(VariableEntry entry, ::cw::lib::Value value,
                                 std::function<void(::cw::lib::Callback)> enqueue)
{
    if (!entry.editable) return false;
    // ネイティブ版の編集は、予約したスナップショット処理の境界をまたぐ。変更を
    // 予約する前に、 Flag の型が違う値や表示中の選択肢にない Step
    // を拒否する。Py ではこの API ではなく型付きの選択画面で制約する。
    const bool valid = std::visit([&](const auto& variable) {
        using T = std::remove_cvref_t<decltype(variable)>;
        if (!variable) return false;
        if constexpr (std::is_same_v<T, std::shared_ptr<::cw::data::Flag>>)
            return std::holds_alternative<bool>(value.storage());
        else if constexpr (std::is_same_v<T, std::shared_ptr<::cw::data::Step>>) {
            const auto index = std::get_if<Integer>(&value.storage());
            // Step の編集では表示中の選択肢スナップショットの行番号を渡す。ワーカーでの変更を予約する前に検証する。
            const auto count = entry.display ? entry.display->choices.size() : variable->m_valuenames.size();
            return index && *index >= 0 && static_cast<std::size_t>(*index) < count;
        } else return true;
    }, entry.variable);
    if (!valid) return false;
    if (!enqueue) {
        if (!::cw::g_cwpy) return false;
        enqueue = [](::cw::lib::Callback job) {if (::cw::g_cwpy) ::cw::g_cwpy->exec_func(std::move(job));};
    }
    std::weak_ptr<::cw::frame::Frame> frame;
    std::weak_ptr<VariableListCtrl> expected;
    if (const auto parent = m_parent.lock()) {
        frame = parent->m_parent;
        if (parent->m_view_var.get() == this) expected = parent->m_view_var;
    }
    const auto once = std::make_shared<std::atomic_bool>(false);
    try {
        enqueue([entry = std::move(entry), value = std::move(value), frame, expected, once](const auto&, const auto&) {
            if (once->exchange(true)) return ::cw::lib::Value{};
            ::cw::lib::String error;
            try {
                std::visit([&](const auto& variable) {
                    using T = std::remove_cvref_t<decltype(variable)>;
                    if constexpr (std::is_same_v<T, std::shared_ptr<::cw::data::Flag>>) {
                        variable->set(value_bool(value));
                        variable->redraw_cards(-1, false);
                    } else if constexpr (std::is_same_v<T, std::shared_ptr<::cw::data::Step>>)
                        variable->set(value_integer(value));
                    else variable->set(value, true);
                    variable->write_value();
                }, entry.variable);
                VariableListCtrl::_update_variablesowner();
            } catch (const std::exception& ex) {error = ex.what();}
            catch (...) {error = "状態変数の変更に失敗しました。";}
            std::optional<VariableEntry> updated;
            try { updated = snapshot_entry(entry); } // 表示文字列は Frame ではなくゲームワーカーで取得する。
            catch (const std::exception& ex) {error = ex.what();}
            catch (...) {error = "状態変数の表示値を取得できませんでした。";}
            post_debugger_ui(frame, [updated, expected, error](Debugger& debugger) {
                const auto view = expected.lock();
                if (!view || debugger.m_view_var != view || !debugger.m_visible) return;
                view->m_last_error = error;
                debugger.m_last_error = error;
                view->m_last_refreshed_row = -1;
                for (std::size_t i = 0; i < view->m_list.size(); ++i)
                    if (updated && view->m_list[i].variable == updated->variable) {
                        view->m_list[i].display = updated->display;
                        view->m_last_refreshed_row = static_cast<Integer>(i);
                    }
                redraw_variable_presentation(debugger);
            });
            return ::cw::lib::Value{};
        });
        m_last_error.clear();
        return true;
    } catch (const std::exception& ex) {m_last_error = ex.what();}
    catch (...) {m_last_error = "状態変数の変更を予約できませんでした。";}
    once->store(true); // ディスパッチャーが処理を予約した後で例外を投げた場合、その処理を後から実行して状態を変更しない。
    if (const auto parent = m_parent.lock()) {parent->m_last_error = m_last_error;redraw_variable_presentation(*parent);}
    return false;
}

::cw::lib::String VariableListCtrl::OnGetItemText(::cw::lib::Integer arg_row, ::cw::lib::Integer arg_col)
{
    if (arg_row < 0 || static_cast<std::size_t>(arg_row) >= m_list.size() || arg_col < 0 || arg_col > 1)
        return {};
    const auto& entry = m_list[static_cast<std::size_t>(arg_row)];
    // 通常の一覧・行更新では、不変な表示値を公開する。独立したモ
    // デルと互換用ヘルパーでは、生のエントリも引き続き扱える。
    if (entry.display) return arg_col == 0 ? entry.display->name : entry.display->value;
    if (arg_col == 0) {
        return std::visit([](const auto& variable) -> ::cw::lib::String {
            using T = std::remove_cvref_t<decltype(variable)>;
            if (!variable)
                return {};
            if constexpr (std::is_same_v<T, std::shared_ptr<::cw::data::Variant>>)
                return value_string(variable->m_name);
            else
                return variable->m_name;
        }, entry.variable);
    }
    return std::visit([](const auto& variable) -> ::cw::lib::String {
        using T = std::remove_cvref_t<decltype(variable)>;
        if (!variable)
            return {};
        if constexpr (std::is_same_v<T, std::shared_ptr<::cw::data::Flag>>)
            return variable->get_valuename(variable->m_value);
        else if constexpr (std::is_same_v<T, std::shared_ptr<::cw::data::Step>>)
            return variable->get_valuename(variable->m_value);
        else
            return ::cw::data::Variant::value_to_str(variable->m_value, true);
    }, entry.variable);
}

::cw::lib::Integer VariableListCtrl::OnGetItemImage(::cw::lib::Integer arg_row)
{
    if (arg_row < 0 || static_cast<std::size_t>(arg_row) >= m_list.size())
        return -1;
    const auto& entry = m_list[static_cast<std::size_t>(arg_row)];
    return std::visit([&](const auto& variable) -> ::cw::lib::Integer {
        using T = std::remove_cvref_t<decltype(variable)>;
        if (!variable)
            return -1;
        if constexpr (std::is_same_v<T, std::shared_ptr<::cw::data::Flag>>)
            return entry.local ? m_imgidx_flag_l : m_imgidx_flag;
        else if constexpr (std::is_same_v<T, std::shared_ptr<::cw::data::Step>>)
            return entry.local ? m_imgidx_step_l : m_imgidx_step;
        else
            return entry.local ? m_imgidx_variant_l : m_imgidx_variant;
    }, entry.variable);
}

VariableListCtrl::VariableEntry VariableListCtrl::snapshot_entry(VariableEntry entry)
{
    VariableDisplay display;
    // スカラー値は値としてコピーされるが、リストや構造体のコモンは変更可能な保
    // 持オブジェクトを所有する。 値の選択画面にゲーム側の実体を保持させない。
    // Py の直接的な変数参照とは異なり、UI には値のグラフをコピーして渡す
    // 。 メモを使い、そのスナップショット内の共有参照と循環参照を維持する。
    std::map<const ::cw::lib::Object*, ::cw::lib::ObjectPtr> copied;
    std::function<::cw::lib::Value(const ::cw::lib::Value&)> copy_value;
    copy_value = [&](const ::cw::lib::Value& value) -> ::cw::lib::Value {
        const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value.storage());
        if (!object || !*object) return value;
        if (const auto found = copied.find(object->get()); found != copied.end())
            return ::cw::lib::Value(found->second);
        if (const auto sequence = std::dynamic_pointer_cast<::cw::data::VariantSequence>(*object)) {
            const auto result = std::make_shared<::cw::data::VariantSequence>();
            copied.emplace(object->get(), result);
            for (const auto& member : sequence->m_values) result->m_values.push_back(copy_value(member));
            return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(result));
        }
        if (const auto structure = std::dynamic_pointer_cast<::cw::data::StructVal>(*object)) {
            const auto result = std::make_shared<::cw::data::StructVal>();
            copied.emplace(object->get(), result);
            result->m_name = copy_value(structure->m_name);
            result->m_member_names = structure->m_member_names;
            for (const auto& member : structure->m_member_values)
                result->m_member_values.push_back(copy_value(member));
            result->m_members = copy_value(structure->m_members);
            return ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(result));
        }
        // 任意のネイティブ Object には安全な不変コピーの保証がない。 変更
        // 可能なゲームオブジェクトを UI に渡すのではなく、取得を失敗させる。
        throw std::invalid_argument("未対応のコモン値を表示用に複製できません。");
    };
    std::visit([&](const auto& variable) {
        using T = std::remove_cvref_t<decltype(variable)>;
        if (!variable) return;
        if constexpr (std::is_same_v<T, std::shared_ptr<::cw::data::Variant>>) {
            display.name = value_string(variable->m_name);
            display.raw_value = copy_value(variable->m_value);
            display.value = ::cw::data::Variant::value_to_str(display.raw_value, true);
        } else {
            display.name = variable->m_name;
            display.raw_value = ::cw::lib::Value(variable->m_value);
            display.value = variable->get_valuename(variable->m_value);
            if constexpr (std::is_same_v<T, std::shared_ptr<::cw::data::Flag>>)
                display.choices = {variable->m_truename, variable->m_falsename};
            else display.choices = variable->m_valuenames;
        }
    }, entry.variable);
    if (entry.local && ::cw::g_cwpy && ::cw::g_cwpy->m_event &&
        ::cw::g_cwpy->m_event->m_in_inusecardevent) {
        const auto card = ::cw::g_cwpy->m_event->get_inusecard();
        const auto scenario = scenario_data();
        if (card && *card && scenario)
            display.different_scenario = value_string(scenario->m_name) != (*card)->m_scenario ||
                                         value_string(scenario->m_author) != (*card)->m_author;
    }
    entry.display = std::move(display);
    return entry;
}

VariableListCtrl::Snapshot VariableListCtrl::collect_variables(
    std::shared_ptr<::cw::event::Event> event,
    std::shared_ptr<::cw::data::SystemData> global, bool local_editable)
{
    Snapshot result;
    const auto append = [&](const auto& data, bool local, bool editable) {
        const auto group = [&](const auto& variables) {
            Snapshot rows;
            for (const auto& [key, variable] : variables) {
                (void)key;
                if (variable) rows.push_back(snapshot_entry({variable, local, editable}));
            }
            std::stable_sort(rows.begin(), rows.end(), [](const auto& a, const auto& b) {
                return ::cw::util::logical_compare(a.display->name, b.display->name) < 0;
            });
            result.insert(result.end(), rows.begin(), rows.end());
        };
        // Python と同様、ローカル、グローバルの順にまとめ、各スコープ内ではコモン、ステップ、フラグの順に並べる。
        group(data.m_variants);
        group(data.m_steps);
        group(data.m_flags);
    };
    if (event) append(*event, true, local_editable);
    // debug_skin では宿の変数も公開するため、ここでは意図的に SystemData を使う。
    if (global) append(*global, false, true);
    return result;
}

bool VariableListCtrl::queue_refresh(SnapshotSource collect, bool whole_list,
                                    std::function<void(::cw::lib::Callback)> enqueue)
{
    if (!m_initialized || !collect) return false;
    const auto expected = weak_from_this();
    if (expected.expired()) return false;
    if (!enqueue) {
        if (!::cw::g_cwpy) return false;
        enqueue = [](::cw::lib::Callback job) {
            if (::cw::g_cwpy) ::cw::g_cwpy->exec_func(std::move(job));
        };
    }
    const auto frame = m_refresh_frame;
    const auto epoch = whole_list ? m_refresh_epoch.fetch_add(1) + 1 : m_refresh_epoch.load();
    const auto once = std::make_shared<std::atomic_bool>(false);
    const auto publish = [frame, expected, epoch, whole_list](Snapshot rows, ::cw::lib::String error) {
        post_debugger_ui(frame, [expected, epoch, whole_list, rows = std::move(rows), error = std::move(error)]
            (Debugger& debugger) mutable {
            const auto view = expected.lock();
            if (!view || debugger.m_view_var != view || !debugger.m_visible ||
                view->m_refresh_epoch.load() != epoch) return;
            if (!error.empty() || debugger.m_last_error == view->m_last_error)
                debugger.m_last_error = error;
            view->m_last_error = error;
            if (!error.empty()) {
                // ネイティブ版では前回の完全なスナップショットを保持し、Python
                // と同じ再試行が成功するまでエラーを表示する。
                redraw_variable_presentation(debugger);
                if (!whole_list) view->refresh_variablelist(std::nullopt);
                return;
            }
            view->m_last_refreshed_row = -1;
            if (whole_list) {
                view->m_list = std::move(rows);
                view->m_item_count = static_cast<Integer>(view->m_list.size());
                if (view->m_selected_row >= view->m_item_count) view->m_selected_row = -1;
            } else {
                for (const auto& row : rows)
                    for (std::size_t i = 0; i < view->m_list.size(); ++i) {
                        auto& current = view->m_list[i];
                        if (current.variable != row.variable) continue;
                        const bool different = current.display && current.display->different_scenario;
                        current.display = row.display;
                        if (current.display) current.display->different_scenario = different;
                        view->m_last_refreshed_row = static_cast<Integer>(i);
                    }
            }
            redraw_variable_presentation(debugger);
        });
    };
    try {
        enqueue([collect = std::move(collect), expected, epoch, once, publish](const auto&, const auto&) {
            if (once->exchange(true)) return ::cw::lib::Value{};
            const auto view = expected.lock();
            if (!view || view->m_refresh_epoch.load() != epoch) return ::cw::lib::Value{};
            Snapshot rows;
            ::cw::lib::String error;
            try {
                rows = collect(); // ゲームワーカー専用。ここでは UI 所有の一覧を変更しない。
                for (auto& row : rows) if (!row.display) row = snapshot_entry(std::move(row));
            } catch (const std::exception& ex) {error = ex.what();}
            catch (...) {error = "状態変数一覧の取得に失敗しました。";}
            publish(std::move(rows), std::move(error));
            return ::cw::lib::Value{};
        });
        return true;
    } catch (const std::exception& ex) {
        once->store(true);
        publish({}, ex.what());
    } catch (...) {
        once->store(true);
        publish({}, "状態変数一覧の更新を予約できませんでした。");
    }
    return false;
}

void VariableListCtrl::refresh_variable(::cw::lib::Value arg_variable)
{
    std::optional<Variable> variable;
    if (auto flag = object_value<::cw::data::Flag>(arg_variable)) variable = flag;
    else if (auto step = object_value<::cw::data::Step>(arg_variable)) variable = step;
    else if (auto variant = object_value<::cw::data::Variant>(arg_variable)) variable = variant;
    if (!variable) return;
    queue_refresh([variable = *variable] { return Snapshot{snapshot_entry({variable, false, false})}; }, false);
}

void VariableListCtrl::refresh_variablelist(std::optional<std::shared_ptr<::cw::event::Event>> arg_event)
{
    refresh_variablelist_impl(std::move(arg_event));
}

void VariableListCtrl::refresh_variablelist_impl(std::optional<std::shared_ptr<::cw::event::Event>> arg_event)
{
    queue_refresh([event = std::move(arg_event)]() mutable -> Snapshot {
        if (!::cw::g_cwpy) return {};
        const auto nowrunning = ::cw::g_cwpy->m_event ?
            ::cw::g_cwpy->m_event->get_nowrunningevent() : std::optional<std::shared_ptr<::cw::event::Event>>{};
        if (!event) event = nowrunning;
        auto global = system_data();
        const auto scenario = std::dynamic_pointer_cast<::cw::data::ScenarioData>(global);
        // シナリオ開始・再開時には ScenarioData が有効になって
        // いても、パーティーと宿の公開が追いつくまで is_playingscenario()
        // が一時的に false になる。この短い生存期間のずれ
        // によって、デバッガーの一覧をローカル変数だけにしない。
        if (!::cw::g_cwpy->is_playingscenario() && !debug_skin_enabled() &&
            !(scenario && scenario->m_is_playing)) return {};
        const bool editable = event && nowrunning && *event == *nowrunning;
        const bool has_yado = ::cw::g_cwpy->m_ydata && *::cw::g_cwpy->m_ydata;
        // Python の if cw.cwpy.ydata: extend(cw.cwpy.sdata,
        // ...) は、ScenarioData と YadoData が
        // 同時に公開されることを前提とする。 C++ では別々の段階で公開す
        // るため、m_ydata だけで判定すると、一時的に現在のイベント
        // のローカルコモンだけが一覧に残る。 有効な ScenarioData
        // があればシナリオ変数と判断できるため、Python の宿の存
        // 在確認はスキンの SystemData に対してだけ維持する。
        if (!has_yado && !scenario)
            global.reset();
#if defined(CARDWIRTH_LOG_ENABLED)
        ::cardwirth::debug::log("Debugger variables collect: local=" +
            std::to_string(event && *event
                ? (*event)->m_variants.size() + (*event)->m_steps.size() + (*event)->m_flags.size()
                : 0) +
            " global=" + std::to_string(global
                ? global->m_variants.size() + global->m_steps.size() + global->m_flags.size()
                : 0) +
            " variants=" + std::to_string(global ? global->m_variants.size() : 0) +
            " steps=" + std::to_string(global ? global->m_steps.size() : 0) +
            " flags=" + std::to_string(global ? global->m_flags.size() : 0) +
            " yado=" + (has_yado ? "1" : "0") +
            " scenario=" + (scenario ? "1" : "0"));
#endif
        return collect_variables(event ? *event : nullptr, global, editable);
    });
}

