void Debugger_OnWaitTime_func(::cw::lib::Integer arg_waittime)
{
    if (::cw::g_cwpy) {
        const auto waittime = std::clamp<Integer>(arg_waittime, 0, 99);
        ::cw::g_cwpy->force_exec_func([waittime](const auto&, const auto&) {
            if (::cw::g_cwpy && ::cw::g_cwpy->m_event)
                ::cw::g_cwpy->m_event->m_waittime = waittime;
            return ::cw::lib::Value{};
        });
    }
}

