{
    if (::cw::g_cwpy)
        ::cw::g_cwpy->force_exec_func([](const auto&, const auto&) {
            if (::cw::g_cwpy && ::cw::g_cwpy->m_event)
                ::cw::g_cwpy->m_event->m_waittime = 0;
            return ::cw::lib::Value{};
        });
}

