void Debugger_exec_editor_func(std::shared_ptr<::cw::debug::debugger::Debugger> arg_parent, std::vector<::cw::lib::String> arg_seq)
{
    if (!arg_parent || arg_seq.empty())
        return;
    try {
        ::cw::lib::ProcessOptions options;
        options.executable = arg_seq.front();
        options.arguments.assign(arg_seq.begin() + 1, arg_seq.end());
        ::cw::lib::ExternalProcess::start_detached(options);
        if (arg_seq.size() > 1)
            arg_parent->m_editor_path = arg_seq[1];
        arg_parent->m_last_error.clear();
        arg_parent->m_operation_log.push_back("launch_editor");
    } catch (const std::exception& error) {
        arg_parent->m_last_error = error.what();
    } catch (...) {
        arg_parent->m_last_error = "editor launch failed";
    }
    if (arg_parent && !arg_parent->m_last_error.empty()) {
        (void)::cw::dialog::message::show_common_modal_message(
            "エラー",
            "シナリオエディタの実行に失敗しました。\n"
            "設定の [シナリオ] > [外部アプリ] > [エディタ] に"
            "適切なエディタを指定してください。",
            false, true);
    }
}

