void Debugger_OnFriendTool_func(std::set<::cw::lib::Integer> arg_friendids, std::vector<std::tuple<::cw::lib::Integer, ::cw::lib::String>> arg_seq, std::vector<::cw::lib::Integer> arg_indices)
{
    const auto scenario = scenario_data();
    if (!scenario || !::cw::g_cwpy)
        return;
    std::set<::cw::lib::Integer> selected = arg_friendids;
    for (const auto index : arg_indices) {
        if (index < 0 || static_cast<std::size_t>(index) >= arg_seq.size())
            continue;
        const auto id = std::get<0>(arg_seq[static_cast<std::size_t>(index)]);
        if (selected.contains(id))
            selected.erase(id);
        else
            selected.insert(id);
    }
    if (selected.size() > 6)
        return;
    for (const auto id : selected)
        if (!scenario->get_castdata(id, "", true, std::nullopt))
            return;
    for (auto it = scenario->m_friendcards.begin(); it != scenario->m_friendcards.end();) {
        if (!*it || !selected.contains((*it)->m_id))
            it = scenario->m_friendcards.erase(it);
        else
            ++it;
    }
    std::set<::cw::lib::Integer> present;
    for (const auto& card : scenario->m_friendcards)
        if (card)
            present.insert(card->m_id);
    for (const auto id : selected) {
        if (present.contains(id) || scenario->m_friendcards.size() >= 6)
            continue;
        const auto data = scenario->get_castdata(id, "", true, std::nullopt);
        if (!data || !*data)
            continue;
        auto card = std::make_shared<::cw::sprite::card::FriendCard>();
        card->initialize(::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(*data)),
                         static_cast<::cw::lib::Integer>(scenario->m_friendcards.size()));
        scenario->m_friendcards.push_back(std::move(card));
        present.insert(id);
    }
}

