void Debugger_OnBgmTool_func(::cw::lib::String arg_path)
{
    if (!::cw::g_cwpy)
        return;
    std::shared_ptr<::cw::data::ScenarioData> scenario;
    if (::cw::g_cwpy->m_ydata && *::cw::g_cwpy->m_ydata &&
        (*::cw::g_cwpy->m_ydata)->m_losted_sdata &&
        *(*::cw::g_cwpy->m_ydata)->m_losted_sdata)
        scenario = *(*::cw::g_cwpy->m_ydata)->m_losted_sdata;
    if (!scenario) {
        if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(
                &::cw::g_cwpy->m_sdata.storage()))
            if (object && *object)
                scenario = std::dynamic_pointer_cast<::cw::data::ScenarioData>(*object);
    }
    if (!arg_path.empty()) {
        const bool scenario_material = ::cw::g_cwpy->is_playingscenario() ||
            (::cw::g_cwpy->m_ydata && *::cw::g_cwpy->m_ydata &&
             (*::cw::g_cwpy->m_ydata)->m_losted_sdata &&
             *(*::cw::g_cwpy->m_ydata)->m_losted_sdata);
        const auto resolved = scenario_material && scenario
            ? ::cw::util::get_materialpath(arg_path, ::cw::g_M_MSC, scenario->m_scedir, false, true)
            : ::cw::util::get_materialpathfromskin(arg_path, ::cw::g_M_MSC, true);
        if (resolved.empty())
            return;
        arg_path = ::cw::lib::encoding::path_to_utf8(
            std::filesystem::absolute(::cw::lib::encoding::path_from_utf8(resolved)));
    }
    for (const auto& music : ::cw::thread::CWPy::s_music) {
        if (!music)
            continue;
        if (arg_path.empty())
            music->stop(0);
        else
            music->stop(0);
    }
    if (!arg_path.empty() && !::cw::thread::CWPy::s_music.empty() &&
        ::cw::thread::CWPy::s_music.front()) {
        ::cw::thread::CWPy::s_music.front()->play(
            arg_path, false, true, false, 100, 0, 0, arg_path);
    }
}

