std::optional<std::shared_ptr<::cw::lib::Bitmap>> get_contenticon(std::shared_ptr<::cw::data::CWPyElement> arg_content)
{
    if (!arg_content)
        return std::nullopt;
    auto name = ::cw::lib::String{"EVT_"} + ::cw::lib::encoding::python_upper(arg_content->m_tag);
    if (arg_content->m_attributes.contains("type"))
        name += "_" + ::cw::lib::encoding::python_upper(arg_content->get("type", ""));
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_rsrc) return std::nullopt;
    // Py の rsrc.debugs.get(key, None) と同様、共通の遅延読み込みリソース表を使う
    // 。 空の type を指定した場合も「_」を付け、Unicode の大文字化には Python の str.upper
    // と同じ規則を使う。 存在しないアイコンを、推測した PNG ファイル名を開いて補わない。
    const auto* table_object = std::get_if<::cw::lib::ObjectPtr>(
        &::cw::g_cwpy->m_rsrc->m_debugs.storage());
    const auto table = table_object && *table_object
        ? std::dynamic_pointer_cast<::cw::setting::ResourceTable>(*table_object) : nullptr;
    if (!table) return std::nullopt;
    const auto value = table->get(::cw::lib::Value(name), ::cw::lib::Value{});
    if (!value) return std::nullopt;
    const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value->storage());
    const auto bitmap = object && *object
        ? std::dynamic_pointer_cast<::cw::lib::Bitmap>(*object) : nullptr;
    return bitmap ? std::optional<std::shared_ptr<::cw::lib::Bitmap>>(bitmap) : std::nullopt;
}

