void StackTraceView_refresh_stackinfo_func_func(std::shared_ptr<::cw::debug::debugger::StackTraceView> arg_self, std::optional<std::shared_ptr<::cw::event::Event>> arg_nowrunning, std::optional<std::shared_ptr<::cw::data::CWPyElement>> arg_cur_content, std::vector<std::optional<::cw::lib::Value>> arg_stackinfo)
{
    if (!arg_self)
        return;
    StackTraceSnapshot snapshot;
    for (auto& item : arg_stackinfo)
        snapshot.frames.push_back(item ? StackTraceView::capture_item(std::move(*item)) : std::nullopt);
    if (arg_nowrunning && *arg_nowrunning)
        snapshot.active=StackTraceView::capture_active(*arg_nowrunning,std::move(arg_cur_content));
    arg_self->apply_snapshot(std::move(snapshot));
}

